def _parse_referral_bot_target(value: str):
    """Accept @username, username, t.me/username, or an optional ?start= link."""
    raw = str(value or "").strip()
    if not raw:
        return None
    bare = re.fullmatch(r"@?([A-Za-z0-9_]{5,32})", raw)
    if bare:
        return bare.group(1), None
    linked = re.fullmatch(
        r"(?:https?://)?(?:www\.)?(?:t\.me|telegram\.me)/"
        r"([A-Za-z0-9_]{5,32})/?(?:\?start=([A-Za-z0-9_-]{1,64}))?",
        raw, re.IGNORECASE,
    )
    if linked:
        return linked.group(1), linked.group(2)
    return None



# ---------------------------------------------------------------------------
# Scoped, private progress panels for finite (time-bounded) operations.
# This helper is deliberately opt-in: persistent background protections must
# not create progress panels, and callers must pass the actual command actor.
# ---------------------------------------------------------------------------
class RemoteProgressPanel:
    """A progress message delivered only to the command executor.

    Scope identity is (remote_name, actor_id, task_id); panels belonging to
    different remotes or actors are never looked up or edited interchangeably.
    `bot` is the Telethon bot client (for example `gbot`).
    """

    _active: Dict[tuple, "RemoteProgressPanel"] = {}
    _registry_lock = asyncio.Lock()

    def __init__(self, bot, actor_id: int, remote_name: str, title: str, *,
                 min_edit_interval: float = 1.5):
        self.bot = bot
        self.actor_id = int(actor_id)
        self.remote_name = str(remote_name)
        self.title = str(title)
        self.task_id = uuid.uuid4().hex[:12]
        self.key = (self.remote_name, self.actor_id, self.task_id)
        self.message = None
        self.total = None
        self.current = 0
        self.status = "در حال آماده‌سازی"
        self.min_edit_interval = max(0.5, float(min_edit_interval))
        self._last_edit = 0.0
        self._lock = asyncio.Lock()
        self._closed = False

    @classmethod
    async def active_for(cls, remote_name: str, actor_id: int):
        prefix = (str(remote_name), int(actor_id))
        async with cls._registry_lock:
            return [p for k, p in cls._active.items()
                    if k[:2] == prefix and not p._closed]

    def _render(self, status=None):
        total = self.total
        current = max(0, int(self.current))
        if total is None or int(total) <= 0:
            percent = 0
            bar = "░" * 10
            count = f"{current:,} / —"
        else:
            total = int(total)
            percent = min(100, int(current * 100 / total))
            filled = min(10, max(0, percent // 10))
            bar = "█" * filled + "░" * (10 - filled)
            count = f"{min(current, total):,} / {total:,}"
        label = status or self.status
        return (f"📊 {self.title}\n"
                f"━━━━━━━━━━━━━━━━━━\n"
                f"ریموت: {self.remote_name}\n"
                f"شناسه اجرا: {self.task_id}\n"
                f"پیشرفت: [{bar}] {percent}%\n"
                f"انجام‌شده: {count}\n"
                f"وضعیت: {label}")

    async def start(self, *, total=None, status="شروع شد"):
        async with self._lock:
            if self.message is not None:
                return self.message
            self.total = total
            self.status = status
            # Recipient is always the actor who invoked this command.
            self.message = await self.bot.send_message(self.actor_id, self._render())
            async with self._registry_lock:
                self._active[self.key] = self
            self._last_edit = time.monotonic()
            return self.message

    async def update(self, *, current=None, total=None, status=None, force=False):
        async with self._lock:
            if self._closed:
                return False
            if current is not None:
                self.current = max(0, int(current))
            if total is not None:
                self.total = max(0, int(total))
            if status is not None:
                self.status = str(status)
            now = time.monotonic()
            if not force and now - self._last_edit < self.min_edit_interval:
                return False
            if self.message is None:
                return False
            await self.bot.edit_message(self.actor_id, self.message.id, self._render())
            self._last_edit = now
            return True

    async def finish(self, status="با موفقیت تمام شد"):
        async with self._lock:
            if self._closed:
                return
            self.status = status
            if self.total is not None:
                self.current = max(self.current, int(self.total))
            if self.message is not None:
                await self.bot.edit_message(self.actor_id, self.message.id, self._render())
            self._closed = True
            async with self._registry_lock:
                self._active.pop(self.key, None)

    async def fail(self, error):
        safe_error = str(error).replace("\r", " ").replace("\n", " ")[:300]
        await self.finish(f"با خطا متوقف شد: {safe_error}")


