# A Telegram .session file must not be opened by two running copies of this bot.
# The OS releases this lock automatically when the process exits/crashes.
_INSTANCE_LOCK_HANDLE = None

def _acquire_single_instance_lock() -> None:
    global _INSTANCE_LOCK_HANDLE
    lock_path = os.path.join(_PERSISTENT_ROOT, ".nobati-instance.lock")
    os.makedirs(os.path.dirname(lock_path) or ".", exist_ok=True)
    handle = open(lock_path, "a+b")
    try:
        if os.name == "nt":
            import msvcrt
            handle.seek(0, os.SEEK_END)
            if handle.tell() == 0:
                handle.write(b"0")
                handle.flush()
            handle.seek(0)
            msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
        else:
            import fcntl
            fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except (OSError, BlockingIOError) as exc:
        handle.close()
        raise RuntimeError(
            "Another Nobati process is already running with this data/session directory"
        ) from exc
    _INSTANCE_LOCK_HANDLE = handle


def _migrate_legacy_runtime_files() -> None:
    """Copy existing local state to a newly attached Railway Volume, without overwriting it."""
    legacy_roots = (
        (os.path.join(PROJECT_DIR, "data"), DATA_DIR),
        (os.path.join(PROJECT_DIR, "sessions"), SESSIONS_DIR),
    )
    for source_root, target_root in legacy_roots:
        if os.path.realpath(source_root) == os.path.realpath(target_root):
            continue
        if not os.path.isdir(source_root):
            continue
        for root, dirs, files in os.walk(source_root):
            dirs[:] = [d for d in dirs if d not in {"__pycache__"}]
            relative = os.path.relpath(root, source_root)
            destination_dir = target_root if relative == "." else os.path.join(target_root, relative)
            os.makedirs(destination_dir, exist_ok=True)
            for filename in files:
                src = os.path.join(root, filename)
                dst = os.path.join(destination_dir, filename)
                if os.path.exists(dst):
                    continue
                try:
                    shutil.copy2(src, dst)
                except OSError as exc:
                    logging.warning("[storage] could not migrate %s: %s", src, exc)


_migrate_legacy_runtime_files()

def sess_path(name: str) -> str:
    os.makedirs(SESSIONS_DIR, exist_ok=True)
    return os.path.join(SESSIONS_DIR, name)

def _sanitize_existing_twofa_log() -> None:
    """Redact any historical plaintext 2FA secrets before normal startup continues."""
    if not os.path.exists(TWOFA_LOG):
        return
    try:
        with open(TWOFA_LOG, "r", encoding="utf-8", errors="replace") as f:
            old_lines = f.readlines()
        safe_lines = []
        for line in old_lines:
            timestamp = line.split("|", 1)[0].strip()
            if not timestamp:
                timestamp = datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S")
            match = re.search(r"\bsess=([^|]+)", line)
            session = re.sub(r"[^A-Za-z0-9_.-]", "_", match.group(1).strip()) if match else "unknown"
            safe_lines.append(f"{timestamp} | sess={session} | 2FA secret redacted\n")
        fd, temp_path = tempfile.mkstemp(dir=os.path.dirname(TWOFA_LOG) or ".", suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                f.writelines(safe_lines)
            os.replace(temp_path, TWOFA_LOG)
        except Exception:
            try:
                os.unlink(temp_path)
            except OSError:
                pass
            raise
    except Exception as exc:
        logging.warning(f"[2fa-log] failed to redact existing log: {exc}")

def save_2fa_to_file(sess: str, phone: str, pwd: str) -> None:
    """Compatibility shim: record that 2FA was handled, never persist the secret."""
    try:
        os.makedirs(DATA_DIR, exist_ok=True)
        line = f"{datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')} | sess={sess} | 2FA secret omitted\n"
        with open(TWOFA_LOG, "a", encoding="utf-8") as f:
            f.write(line)
    except Exception as exc:
        log.warning(f"[2fa-log] write error: {exc}")

_sanitize_existing_twofa_log()

def grp_sess_path(group_name: str, name: str) -> str:

    _safe_gname = re.sub(r'[^A-Za-z0-9_\-]', '_', group_name)
    _safe_name  = re.sub(r'[^A-Za-z0-9_\-]', '_', os.path.basename(name))
    d = os.path.join(SESSIONS_DIR, _safe_gname)
    os.makedirs(d, exist_ok=True)
    return os.path.join(d, _safe_name)

def tmp_sess_path(name: str) -> str:
    d = os.path.join(SESSIONS_DIR, "tmp")
    os.makedirs(d, exist_ok=True)
    return os.path.join(d, name)

def _burn_pool_lock_for_remote(remote_name: str) -> asyncio.Lock:
    remote_name = str(remote_name)
    lock = _burn_pool_locks.get(remote_name)
    if lock is None:
        lock = asyncio.Lock()
        _burn_pool_locks[remote_name] = lock
    return lock

async def _ensure_burn_client_prewarmed(remote_name: str) -> None:
    """Legacy compatibility: no temporary login clients are created for OTP alerts."""
    # A received Telegram login code must never be replayed into an automated
    # sign-in flow. Keep this coroutine for old call sites, but deliberately do
    # not connect or authorize a MemorySession client.
    return


async def _dispose_burn_temp_client(client: Any, session_name: str, remote_name: str = "") -> None:
    """Log out only the temporary in-memory OTP-burn authorization, never a source session."""
    if not client:
        return
    try:
        if client.is_connected() and await client.is_user_authorized():
            from telethon.tl.functions.auth import LogOutRequest
            await client(LogOutRequest())
            log.info("[otp-burn:%s:%s] temporary MemorySession authorization logged out", remote_name, session_name)
    except Exception as exc:
        log.warning("[otp-burn:%s:%s] temporary logout failed: %s", remote_name, session_name, exc)
    finally:
        try:
            await client.disconnect()
        except Exception:
            pass

async def _stop_remote_burn_pool(remote_name: str) -> None:
    """Stop only one remote's OTP-Burn workers, pending cycle and warm pool."""
    remote_name = str(remote_name)
    for key, pending in list(_burn_pending.items()):
        if not isinstance(key, tuple) or not key or key[0] != remote_name:
            continue
        _burn_pending.pop(key, None)
        _burn_in_progress.discard(key)
        _burn_trigger_codes.pop(key, None)
        _burn_early_codes.pop(key, None)
        await _dispose_burn_temp_client(pending.get("client"), str(key[1]), remote_name)
    lock = _burn_pool_lock_for_remote(remote_name)
    async with lock:
        clients = _burn_pools.pop(remote_name, [])
    for client in clients:
        await _dispose_burn_temp_client(client, "pool", remote_name)

async def _send_remote_otp_burn_notice(remote_name: str, text: str) -> None:
    """Send OTP-Burn status only to the owner configured for this remote."""
    remote = groups_db.get(str(remote_name), {})
    try:
        remote_owner = int(remote.get("owner", 0) or 0)
    except (TypeError, ValueError):
        remote_owner = 0
    if not remote_owner:
        log.warning("[otp-burn:%s] remote has no owner; status notice skipped", remote_name)
        return
    try:
        if bot_client and bot_client.is_connected():
            await bot_client.send_message(remote_owner, text, parse_mode="html")
        elif main_client and main_client.is_connected():
            await main_client.send_message(remote_owner, text, parse_mode="html")
    except Exception as exc:
        log.warning("[otp-burn:%s] owner notification failed: %s", remote_name, exc)

def _telegram_login_code_notice(text: str) -> bool:
    """Check for a Telegram login-code notice without returning/extracting the code."""
    value = str(text or "")
    has_code_shape = bool(re.search(r"\b\d{5,6}\b", value))
    if not has_code_shape:
        return False
    context = re.compile(
        r"(?i)(?:login\s+code|code\s+for\s+login|telegram\s+code|your\s+code|"
        r"sign[\s-]?in\s+code|\bcode\b.{0,35}\b(?:login|telegram)\b|"
        r"\b(?:login|telegram)\b.{0,35}\bcode\b|"
        r"کد.{0,40}(?:ورود|تلگرام|تایید|تأیید)|(?:ورود|تلگرام).{0,40}کد)"
    )
    return bool(context.search(value))


def _queue_remote_otp_burn(remote_name: str, session_name: str, code_detected: bool) -> None:
    """Send a redacted, rate-limited login-code alert; never consume/sign in with the code."""
    remote_name = str(remote_name)
    session_name = str(session_name)
    key = (remote_name, session_name)
    if get_group_of_session(session_name) != remote_name or not _otp_burn_enabled_for_session(session_name):
        return
    # Only a boolean detection flag is accepted; the code value is never
    # passed to this function, logged, forwarded, stored, or used for sign-in.
    if not bool(code_detected):
        return
    now = time.monotonic()
    if now - _OTP_ALERT_LAST_SENT.get(key, 0.0) < 30.0:
        return
    _OTP_ALERT_LAST_SENT[key] = now
    notice = (
        f"🔐 <b>هشدار پیام کد ورود</b> — ریموت «{remote_name}»\n"
        f"اکانت: <code>{session_name}</code>\n"
        "تلگرام یک پیام کد ورود فرستاده است. مقدار کد مخفی می‌ماند؛ "
        "هیچ ورود یا مصرف خودکاری انجام نشده است. اگر این درخواست را خودت شروع نکرده‌ای، "
        "نشست‌های حساب را از برنامه رسمی بررسی کن."
    )
    asyncio.create_task(_send_remote_otp_burn_notice(remote_name, notice))


def _attach_burn_only_handler(client: TelegramClient, session_name: str) -> None:
    """Attach a passive, redacted login-alert listener; never consume the code."""
    @client.on(events.NewMessage(from_users=777000))
    async def _passive_login_alert(event):
        remote_name = get_group_of_session(session_name)
        if not remote_name or not _otp_burn_enabled_for_session(session_name):
            return
        # Match presence only; do not extract or forward the numeric value.
        raw_text = event.raw_text or ""
        code_detected = _telegram_login_code_notice(raw_text)
        if code_detected:
            _queue_remote_otp_burn(remote_name, session_name, True)


def _get_session_client_lock(session_name: str) -> asyncio.Lock:
    """Serialize all SQLite-backed client lifecycle operations for one session file."""
    key = str(session_name)
    lock = _SESSION_CLIENT_LOCKS.get(key)
    if lock is None:
        lock = asyncio.Lock()
        _SESSION_CLIENT_LOCKS[key] = lock
    return lock


async def _start_protected_client_unlocked(sess: str) -> None:
    """Keep a disabled source session connected only for passive OTP alerts and Session Guard."""
    if sess in _protected_clients or sess in managed:
        return
    if sess in (MAIN_SESSION, "bot_session"):
        return
    session_file = os.path.join(SESSIONS_DIR, f"{sess}.session")
    if not os.path.exists(session_file):
        return

    client = None
    try:
        _apply_sqlite_wal_to_file(sess_path(sess))
        client = _make_client(
            sess_path(sess), session_name=sess,
            connection_retries=5, retry_delay=2,
        )
        await asyncio.wait_for(client.connect(), timeout=30)
        if not await client.is_user_authorized():
            await client.disconnect()
            return
        _protected_clients[sess] = client
        _attach_burn_only_handler(client, sess)

        if _ghost_enabled_for_session(sess):
            try:
                from telethon.tl.functions.account import UpdateStatusRequest as _USR_GHP
                await client(_USR_GHP(offline=True))
            except Exception:
                pass
        log.warning("[protected] %s started for remote-scoped alert/guard", sess)
    except asyncio.CancelledError:
        if client is not None:
            try:
                await client.disconnect()
            except Exception:
                pass
        raise
    except Exception as exc:
        if client is not None:
            try:
                await client.disconnect()
            except Exception:
                pass
        log.warning(
            "[protected] failed to start %s (%s): %s",
            sess, type(exc).__name__, exc or repr(exc),
        )


async def start_protected_client(sess: str) -> None:
    async with _get_session_client_lock(sess):
        if sess in managed:
            return
        await _start_protected_client_unlocked(sess)


async def _stop_protected_client_unlocked(sess: str) -> None:
    client = _protected_clients.pop(sess, None)
    if client:
        try:
            await client.disconnect()
        except Exception:
            pass


async def stop_protected_client(sess: str) -> None:
    async with _get_session_client_lock(sess):
        await _stop_protected_client_unlocked(sess)

_protected_start_in_flight: set = set()

async def start_protected_client_safe(sess: str) -> None:
    """Start one protected client without racing another start request."""
    if sess in _protected_start_in_flight:
        return
    _protected_start_in_flight.add(sess)
    try:
        await start_protected_client(sess)
    finally:
        _protected_start_in_flight.discard(sess)

async def refresh_protected_clients() -> None:
    """Keep disabled sessions connected only for their own remote's Burn/Guard toggles."""
    for sess in list(_protected_clients.keys()):
        if sess in managed or sess not in manually_disabled or not _session_needs_protected_client(sess):
            asyncio.create_task(stop_protected_client(sess))
    for sess in list(manually_disabled):
        if (sess not in managed and sess not in _protected_clients
                and _session_needs_protected_client(sess)):
            asyncio.create_task(start_protected_client_safe(sess))

