class RemotePendingSelection(dict):
    """Conversation state keyed independently per remote and sender.

    Legacy code can still use pending_group_selection[sender_id]; the active
    remote for that sender is transparently resolved. Remote states remain
    stored under ("remote", remote_name, sender_id), so another remote cannot
    overwrite them.
    """
    def __init__(self):
        super().__init__()
        self._active_remote = {}
        self._last_remote_pop = None

    def _resolve(self, key):
        if isinstance(key, int):
            remote = self._active_remote.get(key)
            if remote is not None:
                scoped = ("remote", remote, key)
                if super().__contains__(scoped):
                    return scoped
        return key

    def __setitem__(self, key, value):
        self._last_remote_pop = None
        if isinstance(key, int) and isinstance(value, dict) and value.get("og_gname"):
            remote = str(value["og_gname"])

            super().pop(key, None)
            super().__setitem__(("remote", remote, key), value)
            self._active_remote[key] = remote
            return
        if isinstance(key, int):
            self._active_remote.pop(key, None)
        super().__setitem__(key, value)

    def __getitem__(self, key):
        self._last_remote_pop = None
        return super().__getitem__(self._resolve(key))

    def get(self, key, default=None):
        self._last_remote_pop = None
        return super().get(self._resolve(key), default)

    def pop(self, key, *default):
        if isinstance(key, int):

            if key == OWNER_ID and self._last_remote_pop is not None:
                sender, remote = self._last_remote_pop
                self._last_remote_pop = None
                if sender != OWNER_ID:
                    if remote is None:
                        return super().pop(OWNER_ID, *default)
                    if self._active_remote.get(OWNER_ID) == remote:
                        self._active_remote.pop(OWNER_ID, None)
                        return super().pop(("remote", remote, OWNER_ID), *default)
                    if default:
                        return default[0]
                    raise KeyError(key)
                if default:
                    return default[0]
                raise KeyError(key)
            self._last_remote_pop = None
            remote = self._active_remote.pop(key, None)
            self._last_remote_pop = (key, remote)
            if remote is not None:
                return super().pop(("remote", remote, key), *default)
            return super().pop(key, *default)
        self._last_remote_pop = None
        return super().pop(key, *default)

    def __contains__(self, key):
        self._last_remote_pop = None
        return super().__contains__(self._resolve(key))

