_BULK_ACTION_TYPES = {
    "typing": SendMessageTypingAction,
    "voice": SendMessageRecordAudioAction,
    "video": SendMessageUploadVideoAction,
    "sticker": SendMessageChooseStickerAction,
    "vidnote": SendMessageRecordRoundAction,
    "document": SendMessageUploadDocumentAction,
}

def _bulk_action_instance(action_key: str):
    action_cls = _BULK_ACTION_TYPES.get(str(action_key))
    if action_cls is None:
        raise ValueError(f"unknown bulk action: {action_key}")
    if action_key in ("video", "document"):
        return action_cls(progress=0)
    return action_cls()

async def _bulk_resolve_peer(client, chat_id: str):
    """Resolve a numeric dialog ID to an InputPeer for SetTypingRequest."""
    from telethon.tl import types as _bulk_types
    value = str(chat_id).strip()
    if value.lstrip("-").isdigit():
        numeric = int(value)
        try:
            return await client.get_input_entity(numeric)
        except Exception:
            pass
        if numeric < 0:
            raw = abs(numeric)
            if raw > 1000000000000:
                raw -= 1000000000000
            if raw > 0:
                try:
                    return await client.get_input_entity(_bulk_types.PeerChannel(channel_id=raw))
                except Exception:
                    try:
                        entity = await client.get_entity(_bulk_types.PeerChannel(channel_id=raw))
                        return await client.get_input_entity(entity)
                    except Exception:
                        pass
        return None
    try:
        entity = await client.get_entity(value)
        return await client.get_input_entity(entity)
    except Exception:
        return None

async def _start_remote_bulk_action_burst(remote_name: str, chat_id: str, action_key: str) -> None:
    """Restart a three-second transient ChatAction burst for one chat in one remote."""
    remote_name = str(remote_name)
    chat_id = str(chat_id)
    remote_cfg = groups_db.get(remote_name, {})
    bulk_cfg = remote_cfg.get("bulk_action", {}) if isinstance(remote_cfg, dict) else {}
    if (not isinstance(bulk_cfg, dict) or not bulk_cfg.get("enabled")
            or chat_id not in {str(x) for x in bulk_cfg.get("targets", [])}
            or str(bulk_cfg.get("action", "typing")) != str(action_key)):
        return
    key = (remote_name, chat_id)
    previous = _BULK_ACTION_BURSTS.get(key)
    if previous and not previous.done():

        previous.cancel()

    async def _run():
        current = asyncio.current_task()
        deadline = time.monotonic() + 3.0
        peer_cache: Dict[str, Any] = {}
        try:
            while time.monotonic() < deadline:
                remote = groups_db.get(remote_name)
                if not isinstance(remote, dict):
                    break

                session_names = list(dict.fromkeys(remote.get("sessions", [])))
                async def _one(session_name: str):
                    meta = managed.get(session_name)
                    client = meta.get("client") if isinstance(meta, dict) else None
                    if not client:
                        return False
                    try:
                        if not client.is_connected():
                            return False
                        peer = peer_cache.get(session_name)
                        if peer is None:
                            peer = await _bulk_resolve_peer(client, chat_id)
                            if peer is None:
                                return False
                            peer_cache[session_name] = peer

                        rpc_timeout = min(1.75, max(0.05, deadline - time.monotonic()))
                        await asyncio.wait_for(
                            client(SetTypingRequest(peer=peer, action=_bulk_action_instance(action_key))),
                            timeout=rpc_timeout,
                        )
                        return True
                    except asyncio.CancelledError:
                        raise
                    except Exception as exc:
                        peer_cache.pop(session_name, None)
                        log.warning("[bulk-action:%s] %s -> %s failed: %s", remote_name, session_name, chat_id, exc)
                        return False
                await asyncio.gather(*(_one(sn) for sn in session_names), return_exceptions=True)
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    break
                await asyncio.sleep(min(1.0, remaining))
        finally:

            if _BULK_ACTION_BURSTS.get(key) is current:
                remote = groups_db.get(remote_name, {})
                session_names = list(dict.fromkeys(remote.get("sessions", []))) if isinstance(remote, dict) else []
                async def _cancel_indicator(session_name: str):
                    meta = managed.get(session_name)
                    client = meta.get("client") if isinstance(meta, dict) else None
                    if not client:
                        return
                    try:
                        if not client.is_connected():
                            return
                        peer = peer_cache.get(session_name)
                        if peer is None:
                            peer = await _bulk_resolve_peer(client, chat_id)
                        if peer is not None:
                            await asyncio.wait_for(
                                client(SetTypingRequest(peer=peer, action=SendMessageCancelAction())),
                                timeout=1.0,
                            )
                    except Exception as cancel_error:
                        log.debug("[bulk-action:%s] cancel indicator failed for %s: %s", remote_name, session_name, cancel_error)
                await asyncio.gather(*(_cancel_indicator(sn) for sn in session_names), return_exceptions=True)
                if _BULK_ACTION_BURSTS.get(key) is current:
                    _BULK_ACTION_BURSTS.pop(key, None)

    task = asyncio.create_task(_run(), name=f"bulk-action:{remote_name}:{chat_id}")
    _BULK_ACTION_BURSTS[key] = task

def _trigger_remote_bulk_action(remote_name: str, chat_id: str, action_key: str) -> None:
    """Schedule a burst without blocking the incoming-message update handler."""
    try:
        asyncio.create_task(_start_remote_bulk_action_burst(remote_name, chat_id, action_key))
    except RuntimeError:
        log.warning("[bulk-action:%s] no running event loop; trigger skipped", remote_name)
atk_stats: dict = {}

_ATK_START_MONO: Dict[str, float] = {}
_ATK_FIRST_SEND_LOGGED: Set[str] = set()

def _atk_mark_start(key: str) -> None:
    _ATK_START_MONO[key] = time.monotonic()
    _ATK_FIRST_SEND_LOGGED.discard(key)
    log.warning("[atk:%s] start requested; timing first successful delivery", key)

def _atk_log_first_send(key: str) -> None:
    if key in _ATK_FIRST_SEND_LOGGED:
        return
    started = _ATK_START_MONO.get(key)
    if started is None:
        return
    _ATK_FIRST_SEND_LOGGED.add(key)
    elapsed = max(0.0, time.monotonic() - started)
    log.warning("[atk:%s] first successful delivery after %.2fs", key, elapsed)
