async def _fetch_joined_groups(session_names: list) -> list:
    """
    فقط گروه‌هایی که سشن‌های داده‌شده در اون‌ها عضو هستن رو برمی‌گردونه.
    - موازی: همه سشن‌ها همزمان fetch می‌کنن
    - left=True فیلتر میشه
    - هم Chat (گروه معمولی) هم Channel با megagroup=True (سوپرگروه) پشتیبانی میشه
    - برمی‌گردونه: [(name, id), ...] مرتب‌شده بر اساس نام
    """
    from telethon.tl.types import Chat, Channel

    async def _one_session(sess: str) -> dict:
        meta = managed.get(sess)
        if not meta:
            return {}
        client = meta["client"]
        result: dict = {}

        async def _collect():
            async for dialog in client.iter_dialogs():
                entity = getattr(dialog, "entity", None)
                if entity is None:
                    continue

                if getattr(entity, "left", False):
                    continue
                if getattr(entity, "deactivated", False):
                    continue

                if isinstance(entity, Chat):
                    result[dialog.id] = dialog.name or str(dialog.id)

                elif isinstance(entity, Channel) and getattr(entity, "megagroup", False):
                    result[dialog.id] = dialog.name or str(dialog.id)

        try:
            await asyncio.wait_for(_collect(), timeout=45)
        except (asyncio.TimeoutError, Exception):
            pass
        return result

    results = await asyncio.gather(*[_one_session(s) for s in session_names],
                                   return_exceptions=True)
    merged: dict = {}
    for r in results:
        if isinstance(r, dict):
            for gid, name in r.items():
                if gid not in merged:
                    merged[gid] = name

    return sorted([(name, gid) for gid, name in merged.items()],
                  key=lambda x: (x[0] or "").lower())

def _rebuild_sess_grp_index() -> bool:
    """Enforce exactly one remote owner per source session."""
    assigned: Dict[str, str] = {}
    changed = False
    for remote_name, remote_info in groups_db.items():
        if not isinstance(remote_info, dict):
            groups_db[remote_name] = {"sessions": []}
            remote_info = groups_db[remote_name]
            changed = True
        raw_sessions = remote_info.get("sessions", [])
        if not isinstance(raw_sessions, list):
            raw_sessions = []
            changed = True
        clean_sessions = []
        for session_name in raw_sessions:
            if not isinstance(session_name, str) or not session_name.strip():
                changed = True
                continue
            if session_name in assigned:
                changed = True
                log.warning(
                    "[remote-scope] duplicate session %s in remotes %s and %s; keeping %s",
                    session_name, assigned[session_name], remote_name, assigned[session_name],
                )
                continue
            assigned[session_name] = str(remote_name)
            clean_sessions.append(session_name)
        if clean_sessions != remote_info.get("sessions", []):
            remote_info["sessions"] = clean_sessions
            changed = True
    return changed

