def _remote_name_from_callback_data(data: Any) -> Optional[str]:
    if isinstance(data, bytes):
        raw = data.decode("utf-8", errors="ignore")
    else:
        raw = str(data or "")
    if not raw:
        return None
    for remote_name in sorted((str(x) for x in groups_db.keys()), key=len, reverse=True):
        if not remote_name:
            continue
        # callback data carries a remote as a complete suffix or as the token
        # immediately before a pipe-delimited account/index argument.
        if raw.endswith("_" + remote_name) or raw == remote_name or f"_{remote_name}|" in raw:
            return remote_name
    return None


def _remote_panel_language(remote_name: str) -> str:
    info = groups_db.get(str(remote_name), {})
    lang = str(info.get("panel_language", "fa") if isinstance(info, dict) else "fa").lower()
    return "en" if lang == "en" else "fa"


def _translate_button_label(label: str, language: str) -> str:
    """Translate whole button words/phrases only; never corrupt substrings in English words."""
    text = str(label or "")
    language = "en" if str(language).lower() == "en" else "fa"
    mapping = _FA_TO_EN_BUTTON_PHRASES if language == "en" else _EN_TO_FA_BUTTON_PHRASES
    for source_text in sorted(mapping, key=len, reverse=True):
        target_text = mapping[source_text]
        if language == "en":
            # Persian word boundary: do not translate a prefix inside another Persian word.
            pattern = r"(?<![\u0600-\u06FF\u200c])" + re.escape(source_text) + r"(?![\u0600-\u06FF\u200c])"
        else:
            # Latin word boundary: e.g. 'On' must not match inside 'Button'.
            pattern = r"(?<![A-Za-z0-9])" + re.escape(source_text) + r"(?![A-Za-z0-9])"
        text = re.sub(pattern, lambda _m, value=target_text: value, text,
                      flags=re.IGNORECASE if language == "fa" else 0)
    # Use 'Account' rather than 'Session' when a button contains an otherwise-unmapped term.
    if language == "en":
        text = re.sub(r"(?<![\u0600-\u06FF\u200c])سشن(?![\u0600-\u06FF\u200c])", "Account", text)
        text = re.sub(r"(?<![\u0600-\u06FF\u200c])اکانت(?![\u0600-\u06FF\u200c])", "Account", text)
        text = re.sub(r"\bSessions?\b", lambda m: "Accounts" if m.group(0).lower().endswith("s") else "Account", text, flags=re.IGNORECASE)
    else:
        text = re.sub(r"\bSessions?\b", "اکانت", text, flags=re.IGNORECASE)
    return text


def _unfont(text: str) -> str:
    """Reverse the source's decorative ASCII font so dedicated-bot labels can be translated."""
    result = []
    for ch in str(text or ""):
        code = ord(ch)
        if 0x1D63C <= code <= 0x1D655:
            result.append(chr(65 + code - 0x1D63C))
        elif 0x1D656 <= code <= 0x1D66F:
            result.append(chr(97 + code - 0x1D656))
        elif 0x1D7EC <= code <= 0x1D7F5:
            result.append(chr(48 + code - 0x1D7EC))
        else:
            result.append(ch)
    return "".join(result)


def _translate_button_rows(buttons: Any, remote_name: str):
    """Localise button text in a dedicated remote bot, whose callbacks omit remote IDs."""
    if not buttons:
        return buttons
    language = _remote_panel_language(remote_name)
    for row in buttons:
        for button in row:
            label = getattr(button, "text", None)
            if isinstance(label, str):
                try:
                    button.text = _font(_translate_button_label(_unfont(label), language))
                except Exception:
                    pass
    return buttons


def pe(e: str) -> str:
    """پریمیوم ایموجی — emoji رو برمیگردونه؛ entity توسط _apply_custom_emoji ست می‌شه."""
    return e

def _apply_custom_emoji(text: str, parse_mode="html"):
    """Parse text using its active mode and append Telegram custom-emoji entities."""
    try:
        from telethon.tl.types import MessageEntityCustomEmoji
        if parse_mode is None:
            plain, base_ents = str(text), []
        elif hasattr(parse_mode, "parse"):
            plain, base_ents = parse_mode.parse(str(text))
        else:
            mode = str(parse_mode).strip().lower()
            if mode in {"html", "telethon.extensions.html"}:
                from telethon.extensions import html as _tl_html
                plain, base_ents = _tl_html.parse(str(text))
            elif mode in {"md", "markdown", "telethon.extensions.markdown"}:
                from telethon.extensions import markdown as _tl_markdown
                plain, base_ents = _tl_markdown.parse(str(text))
            else:
                plain, base_ents = str(text), []
        ents = list(base_ents or [])
        claimed: List[tuple] = []

        def _overlaps(start, end):
            return any(start < e and end > s for s, e in claimed)

        for emoji, doc_id in sorted(_PREM.items(), key=lambda kv: -len(kv[0])):
            pos = 0
            while True:
                idx = plain.find(emoji, pos)
                if idx == -1:
                    break
                end_idx = idx + len(emoji)
                if _overlaps(idx, end_idx):
                    pos = end_idx
                    continue
                off16 = len(plain[:idx].encode("utf-16-le")) // 2
                len16 = len(emoji.encode("utf-16-le")) // 2
                selected_doc_id = random.choice(doc_id) if isinstance(doc_id, (list, tuple)) else doc_id
                ents.append(MessageEntityCustomEmoji(
                    offset=off16,
                    length=len16,
                    document_id=int(selected_doc_id),
                ))
                claimed.append((idx, end_idx))
                pos = end_idx
        return plain, ents
    except Exception:
        return str(text), []

def _patch_client_premium_emoji():
    """
    یک‌بار برای همیشه send_message/edit_message خودِ TelegramClient رو پچ می‌کنه
    تا هر پیامی که از هر جای ربات (هر bot/gbot/client) فرستاده یا ادیت میشه،
    خودکار از فیلتر _apply_custom_emoji رد بشه و هر ایموجی موجود در _PREM
    به‌صورت ایموجی پرمیوم (MessageEntityCustomEmoji) نمایش داده بشه —
    بدون نیاز به دست‌کاری تک‌تک صدها فراخوانی send_message/edit_message.
    """
    if getattr(TelegramClient, "_premium_emoji_patched", False):
      return
    _orig_send_message = TelegramClient.send_message
    _orig_edit_message = TelegramClient.edit_message

    def _inject_emoji(client, args, kwargs):
      args = list(args)
      text = None
      loc = None
      if isinstance(kwargs.get("message"), str):
          text = kwargs["message"]
          loc = ("kwargs",)
      elif len(args) >= 2 and isinstance(args[1], str):
          text = args[1]
          loc = ("args", 1)
      if text and kwargs.get("formatting_entities") is None:
          try:
              parse_mode = kwargs["parse_mode"] if "parse_mode" in kwargs else getattr(client, "parse_mode", "md")
              plain, ents = _apply_custom_emoji(text, parse_mode=parse_mode)
          except Exception:
              plain, ents = text, []
          if ents:
              if loc[0] == "kwargs":
                    kwargs["message"] = plain
              else:
                    args[1] = plain
              kwargs["formatting_entities"] = ents
              kwargs.pop("parse_mode", None)
      return args, kwargs

    async def _send_message_premium(self, *args, **kwargs):
      args, kwargs = _inject_emoji(self, args, kwargs)
      return await _orig_send_message(self, *args, **kwargs)

    async def _edit_message_premium(self, *args, **kwargs):
      args, kwargs = _inject_emoji(self, args, kwargs)
      return await _orig_edit_message(self, *args, **kwargs)

    TelegramClient.send_message = _send_message_premium
    TelegramClient.edit_message = _edit_message_premium
    TelegramClient._premium_emoji_patched = True

_patch_client_premium_emoji()


def _install_bot_client_message_wrappers(client) -> None:
    """Install the management bot's premium-emoji wrappers once per client."""
    if client is None or getattr(client, "_nobati_message_wrappers_installed", False):
        return
    original_send = client.send_message
    original_edit = client.edit_message

    async def _prem_send(entity, message=None, **kwargs):
        if isinstance(message, str) and message and kwargs.get("formatting_entities") is None:
            parse_mode = kwargs["parse_mode"] if "parse_mode" in kwargs else getattr(client, "parse_mode", "md")
            plain, entities = _apply_custom_emoji(message, parse_mode=parse_mode)
            if entities:
                kwargs.pop("parse_mode", None)
                return await original_send(entity, plain, formatting_entities=entities, **kwargs)
        return await original_send(entity, message, **kwargs)

    async def _prem_edit(entity, message=None, text=None, **kwargs):
        candidate = text if text is not None else message
        if isinstance(candidate, str) and candidate and kwargs.get("formatting_entities") is None:
            parse_mode = kwargs["parse_mode"] if "parse_mode" in kwargs else getattr(client, "parse_mode", "md")
            plain, entities = _apply_custom_emoji(candidate, parse_mode=parse_mode)
            if entities:
                kwargs.pop("parse_mode", None)
                if text is not None:
                    return await original_edit(entity, message, text=plain, formatting_entities=entities, **kwargs)
                return await original_edit(entity, plain, formatting_entities=entities, **kwargs)
        return await original_edit(entity, message, text=text, **kwargs)

    client.send_message = _prem_send
    client.edit_message = _prem_edit
    setattr(client, "_nobati_message_wrappers_installed", True)


