def ensure_sessions_dir():
    try:
      if not os.path.isdir(SESSIONS_DIR):
          os.makedirs(SESSIONS_DIR, exist_ok=True)
    except Exception:
      pass

def per_session_state_path(session_name: str) -> str:
    ensure_sessions_dir()
    return os.path.join(SESSIONS_DIR, f"{session_name}_state.json")

def media_store_dir(session_name: str) -> str:
    ensure_sessions_dir()
    d = os.path.join(SESSIONS_DIR, f"{session_name}_media")
    os.makedirs(d, exist_ok=True)
    return d

def _atomic_write_json(path: str, data) -> None:
    """Write JSON atomically: write to temp file then rename to avoid corruption on crash."""
    import tempfile
    dir_ = os.path.dirname(os.path.abspath(path)) or "."
    try:
      fd, tmp = tempfile.mkstemp(dir=dir_, suffix=".tmp")
      try:
          with os.fdopen(fd, "w", encoding="utf-8") as f:
              json.dump(data, f, ensure_ascii=False, indent=2)
          os.replace(tmp, path)
      except Exception:
          try:
              os.unlink(tmp)
          except Exception:
              pass
          raise
    except Exception as e:

      try:
          with open(path, "w", encoding="utf-8") as f:
              json.dump(data, f, ensure_ascii=False, indent=2)
      except Exception as e2:
          log.warning(f"[atomic_write] {path}: {e2}")

_UNAUTHORIZED_NOTICE_KEYS: Set[str] = set()
_UNAUTHORIZED_NOTICE_LOADED = False

def _load_unauthorized_notice_keys() -> None:
    global _UNAUTHORIZED_NOTICE_LOADED, _UNAUTHORIZED_NOTICE_KEYS
    if _UNAUTHORIZED_NOTICE_LOADED:
        return
    _UNAUTHORIZED_NOTICE_LOADED = True
    try:
        with open(UNAUTHORIZED_NOTICE_DB, "r", encoding="utf-8") as f:
            raw = json.load(f)
        if isinstance(raw, list):
            _UNAUTHORIZED_NOTICE_KEYS = {str(x) for x in raw}
        elif isinstance(raw, dict):
            _UNAUTHORIZED_NOTICE_KEYS = {str(x) for x in raw.get("notified", [])}
    except FileNotFoundError:
        _UNAUTHORIZED_NOTICE_KEYS = set()
    except Exception as e:
        log.warning("[access-gate] could not load one-time notice DB: %s", e)
        _UNAUTHORIZED_NOTICE_KEYS = set()

def _unauthorized_notice_key(scope: str, uid: int) -> str:
    return f"{scope}:{int(uid)}"

def _mark_unauthorized_notice_sent(scope: str, uid: int) -> bool:
    """Atomically reserve a single notice for this user/scope; return True once."""
    key = _unauthorized_notice_key(scope, uid)
    _load_unauthorized_notice_keys()
    if key in _UNAUTHORIZED_NOTICE_KEYS:
        return False
    _UNAUTHORIZED_NOTICE_KEYS.add(key)
    _atomic_write_json(UNAUTHORIZED_NOTICE_DB, sorted(_UNAUTHORIZED_NOTICE_KEYS))
    return True

def _has_unauthorized_notice_been_sent(scope: str, uid: int) -> bool:
    _load_unauthorized_notice_keys()
    return _unauthorized_notice_key(scope, uid) in _UNAUTHORIZED_NOTICE_KEYS

