def load_db() -> None:
    global sessions_db, groups_db, bot_blacklist, manually_disabled, CO_OWNERS, AUTO_DELETE_OFFLINE_24H
    ensure_sessions_dir()
    try:
        if os.path.exists(OFFLINE_AUTO_DELETE_DB):
            with open(OFFLINE_AUTO_DELETE_DB, "r", encoding="utf-8") as f:
                setting = json.load(f)
            AUTO_DELETE_OFFLINE_24H = bool(setting.get("enabled", False)) if isinstance(setting, dict) else False
        else:
            AUTO_DELETE_OFFLINE_24H = False
    except Exception as e:
        AUTO_DELETE_OFFLINE_24H = False
        log.warning("[offline-cleanup] setting file unreadable; defaulting to OFF: %s", e)
    if os.path.exists(SESSIONS_DB):
      try:
          with open(SESSIONS_DB, "r", encoding="utf-8") as f:
              sessions_db = json.load(f)
      except Exception as e:
          log.warning(f"[load_db] sessions.json corrupt/unreadable: {e} — starting empty")
          sessions_db = {}
    else:
      sessions_db = {}
    migrate_session_names()
    if os.path.exists(GROUPS_DB):
      try:
          with open(GROUPS_DB, "r", encoding="utf-8") as f:
              groups_db = json.load(f)
      except Exception as e:
          log.warning(f"[load_db] groups.json corrupt/unreadable: {e} — starting empty")
          groups_db = {}
    else:
      groups_db = {}
    if _rebuild_sess_grp_index():
        _atomic_write_json(GROUPS_DB, groups_db)
    if os.path.exists(BLACKLIST_DB):
      try:
          with open(BLACKLIST_DB, "r", encoding="utf-8") as f:
              bot_blacklist = set(json.load(f))
      except Exception as e:
          log.warning(f"[load_db] blacklist.json corrupt/unreadable: {e} — starting empty")
          bot_blacklist = set()
    else:
      bot_blacklist = set()
    if os.path.exists(DISABLED_DB):
      try:
          with open(DISABLED_DB, "r", encoding="utf-8") as f:
              manually_disabled = set(json.load(f))
      except Exception as e:
          log.warning(f"[load_db] disabled_sessions.json corrupt/unreadable: {e} — starting empty")
          manually_disabled = set()
    else:
      manually_disabled = set()
    if os.path.exists(CO_OWNERS_DB):
      try:
          with open(CO_OWNERS_DB, "r", encoding="utf-8") as f:
              CO_OWNERS.update(json.load(f))
      except Exception as e:
          log.warning(f"[load_db] co_owners.json corrupt/unreadable: {e} — starting empty")
    global GHOST_MODE
    if os.path.exists(GHOST_MODE_DB):
      try:
          with open(GHOST_MODE_DB, "r", encoding="utf-8") as f:
              GHOST_MODE = bool(json.load(f))
      except Exception:
          GHOST_MODE = False

    _ghost_migrated = False
    for _ginfo in groups_db.values():
      if isinstance(_ginfo, dict) and "ghost_mode" not in _ginfo:
          _ginfo["ghost_mode"] = bool(GHOST_MODE)
          _ghost_migrated = True
    if _ghost_migrated:
      try:
          save_groups()
      except Exception as _ghost_save_err:
          log.warning("[ghost] could not persist per-remote migration: %s", _ghost_save_err)
    load_fingerprints()
    load_privacy_hardening_setting()

def _sync_remote_guard_workers(remote_name: Optional[str] = None, restart: bool = False) -> int:
    """Start/stop independent guard workers; each worker reads only its own remote."""
    if remote_name is None:
        selected = set(str(name) for name in groups_db) | set(_remote_guard_tasks)
    else:
        selected = {str(remote_name)}

    active = {
        str(name) for name in selected
        if isinstance(groups_db.get(str(name)), dict)
        and bool(groups_db[str(name)].get("session_guard", False))
        and bool(groups_db[str(name)].get("sessions"))
    }

    for name in selected:
        task = _remote_guard_tasks.get(name)
        if name not in active or restart:
            if task and not task.done():
                task.cancel()
            _remote_guard_tasks.pop(name, None)

    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        return len(active)

    for name in active:
        task = _remote_guard_tasks.get(name)
        if task is None or task.done():
            _remote_guard_tasks[name] = loop.create_task(
                _remote_session_guard(name),
                name=f"session-guard:{name}",
            )
    return len(active)

def _otp_burn_enabled_for_session(session_name: str) -> bool:
    """OTP Burn is enabled only by the one remote that owns this source session."""
    gname = get_group_of_session(session_name)
    if gname is None:
        return False
    remote = groups_db.get(gname, {})
    return bool(isinstance(remote, dict) and session_name in remote.get("sessions", [])
                and remote.get("otp_burn", False))

def _session_guard_enabled_for_session(session_name: str) -> bool:
    """Session Guard is enabled only by the one remote that owns this session."""
    gname = get_group_of_session(session_name)
    if gname is None:
        return False
    remote = groups_db.get(gname, {})
    return bool(isinstance(remote, dict) and session_name in remote.get("sessions", [])
                and remote.get("session_guard", False))

def _session_needs_protected_client(session_name: str) -> bool:
    """A manually disabled session stays connected only for enabled remote features."""
    return _otp_burn_enabled_for_session(session_name) or _session_guard_enabled_for_session(session_name)

async def _cancel_remote_burn_for_session(remote_name: str, session_name: str) -> None:
    """Cancel only the pending OTP-burn attempt for one (remote, session) pair."""
    key = (str(remote_name), str(session_name))
    pending = _burn_pending.pop(key, None)
    _burn_in_progress.discard(key)
    _burn_trigger_codes.pop(key, None)
    _burn_early_codes.pop(key, None)
    if pending:
        await _dispose_burn_temp_client(pending.get("client"), str(session_name), str(remote_name))

def _forget_remote_trust_for_session(remote_name: str, session_name: str) -> None:
    """Remove a moved/removed account's saved authorization hashes from this remote only."""
    remote = groups_db.get(str(remote_name), {})
    entries = remote.get("trusted_devices", []) if isinstance(remote, dict) else []
    if not isinstance(entries, list):
        return
    kept = []
    for item in entries:
        if not isinstance(item, dict):
            continue
        hashes = item.get("session_hashes", {})
        if isinstance(hashes, dict):
            hashes.pop(str(session_name), None)
            item["session_hashes"] = hashes
        if _trusted_hash_count(item) or not isinstance(item.get("session_hashes"), dict):
            kept.append(item)
    if isinstance(remote, dict):
        remote["trusted_devices"] = kept

