    @client.on(events.NewMessage(pattern=re.compile(r'^typingflood\s+(on|off)(?:\s+(.+))?$', re.IGNORECASE)))
    async def cmd_typingflood(event):
      sender = event.sender_id
      if not has_admin_access(sender, session_name=session_name, state=state):
          return
      v   = event.pattern_match.group(1).lower()
      tgt = event.pattern_match.group(2)
      remote_name = get_group_of_session(session_name)
      if not remote_name:
          await minimal_reply(client, event, "این سشن عضو هیچ ریموتی نیست؛ عملیات بین‌ریموتی مجاز نیست.")
          return
      _task_prefix = f"typing_{remote_name}_"
      if v == "off":
          for key in [k for k in flood_tasks if k.startswith(_task_prefix)]:
              t = flood_tasks.pop(key, None)
              if t and not t.done():
                    t.cancel()
          await minimal_reply(client, event, " Typing Flood این ریموت متوقف شد.")
          return
      if not tgt:
          await minimal_reply(client, event, " مقصد رو بنویس.\nمثال: typingflood on @username")
          return
      raw = str(tgt).strip()
      for pfx in ("https://t.me/", "http://t.me/", "t.me/"):
          if raw.startswith(pfx):
              raw = raw[len(pfx):]
      raw = raw.lstrip("@")
      try:
          target = int(raw)
      except ValueError:
          target = raw

      async def _typing_flood_loop():
          while True:
              group_sessions = [s for s in groups_db.get(remote_name, {}).get("sessions", []) if s in managed]
              if not group_sessions:
                    await asyncio.sleep(3)
                    continue
              async def _send_typing(sess):
                    meta = managed.get(sess)
                    if not meta:
                        return
                    try:
                        await meta["client"](SetTypingRequest(
                            peer=target, action=SendMessageTypingAction()))
                    except Exception:
                        pass
              await asyncio.gather(*[_send_typing(s) for s in group_sessions], return_exceptions=True)
              await asyncio.sleep(4)

      key = f"typing_{remote_name}_{target}"
      old = flood_tasks.get(key)
      if old and not old.done():
          old.cancel()
      flood_tasks[key] = asyncio.create_task(_typing_flood_loop())
      await minimal_reply(client, event, f" Typing Flood ریموت {remote_name} شروع شد روی {tgt}\nبرای توقف همین ریموت: typingflood off")

