    def _remote_picker_text(uid: int, groups: list) -> str:
      """Neutral remote picker for remote owners/admins (not the source admin panel)."""
      lines = "\n".join(f"• ریموت {g}" for g in groups)
      return (
          f"{pe('🖥')} پنل ریموت\n"
          f"━━━━━━━━━━━━━━\n"
          f"ریموت‌های در دسترس شما:\n\n"
          f"{lines}\n"
          f"━━━━━━━━━━━━━━\n"
          f"یه ریموت انتخاب کن:"
      )

    def _remote_picker_buttons(groups: list) -> list:
      rows = []
      for gname in groups:
          info = groups_db.get(gname, {})
          cnt = len(info.get("sessions", []))
          online = sum(1 for s in info.get("sessions", []) if s in managed)
          rows.append([Button.inline(f"🟢 {gname}  [{online}/{cnt} آنلاین]",
              f"og_home_{gname}".encode()
          )])
      return rows

    @bot.on(events.NewMessage(pattern=re.compile(r'^/(start|panel)(?:@[A-Za-z0-9_]+)?(?:\s+(.+))?$', re.IGNORECASE)))
    async def bot_start(event):
      uid = event.sender_id
      chat_id = event.chat_id
      try:
          # Do not delete /start or the current panel until a replacement panel
          # has been delivered successfully. This prevents a silent dead-end.
          if owner_guard(event):
              btns = main_menu_buttons()
              sent = await sp(chat_id, _build_main_panel_text(), buttons=btns)
          else:
              remote_groups = _user_og_admin_groups(uid)
              if remote_groups:
                  btns = _remote_picker_buttons(remote_groups)
                  sent = await sp(chat_id, _remote_picker_text(uid, remote_groups), buttons=btns)
              else:
                  sent = await bot.send_message(chat_id, "برای این حساب ریموتی جهت مدیریت ثبت نشده است.")
          if sent:
              try:
                  await event.delete()
              except Exception as exc:
                  log.debug("[owner-panel] could not delete /start message chat_id=%s: %s", chat_id, exc)
      except Exception as exc:
          log.exception("[owner-panel] /start failed chat_id=%s sender_id=%s", chat_id, uid)
          try:
              await event.reply("ارسال پنل با خطا روبه‌رو شد؛ پیام /start حذف نشد. لطفاً دوباره تلاش کنید.")
          except Exception:
              pass

