    # Referral Bot is remote-scoped: each panel/config/operation uses only
    # the sessions currently assigned to the selected remote.
    _og_referral_locks = {}

    def _og_referral_cfg(gname):
      info = groups_db.setdefault(gname, {})
      cfg = info.setdefault("referral_bot", {})
      if not isinstance(cfg, dict):
          cfg = {}
          info["referral_bot"] = cfg
      cfg.setdefault("link", "")
      cfg.setdefault("done_sessions", [])
      cfg.setdefault("last_results", {})
      cfg.setdefault("last_result", "")
      cfg.setdefault("button_options", [])
      cfg.setdefault("extract_session", "")
      return cfg

    def _og_referral_buttons(gname):
      cfg = _og_referral_cfg(gname)
      rows = [
          [Button.inline("🔗 ثبت لینک استارت", f"ogref_link_{gname}".encode())],
          [Button.inline("▶️ اجرای عملیات ریموت", f"ogref_run_{gname}".encode())],
      ]
      for i, item in enumerate(cfg.get("button_options") or []):
          label = str(item.get("text") or f"گزینه {i+1}")[:42]
          rows.append([Button.inline(f"🖱 انتخاب: {label}", f"ogref_choose_{gname}_{i}".encode())])
      rows.append([Button.inline("🔙 بازگشت به منوی ریموت", f"og_home_{gname}".encode())])
      return rows

    def _og_referral_text(gname):
      cfg = _og_referral_cfg(gname)
      sessions = list(dict.fromkeys(og_sessions(gname)))
      online = [x for x in sessions if managed.get(x) and managed[x].get("client")]
      done = set(cfg.get("done_sessions") or [])
      opts = cfg.get("button_options") or []
      labels = "\n".join(f"{i+1}. {x.get('text','')}" for i, x in enumerate(opts)) or "هنوز دکمه‌ای استخراج نشده"
      return (f"🎟 Referral Bot — ریموت {gname}\n━━━━━━━━━━━━━━━━━━\n"
              f"لینک: {cfg.get('link') or '— ثبت نشده —'}\n"
              f"سشن‌های همین ریموت: {len(sessions)} | آنلاین: {len(online)} | قبلاً موفق: {len(done.intersection(sessions))}\n"
              f"سشن استخراج‌کننده: {cfg.get('extract_session') or '—'}\n"
              f"دکمه‌های شناسایی‌شده:\n{labels}\n"
              f"نتیجه آخر: {cfg.get('last_result') or '—'}\n━━━━━━━━━━━━━━━━━━\n"
              "تنظیمات و عملیات این بخش فقط به سشن‌های همین ریموت محدود است.")

