    @bot.on(events.CallbackQuery(pattern=re.compile(rb"ogref_run_(.+)")))
    async def _og_referral_run_cb(event):
      gname = event.pattern_match.group(1).decode(errors="ignore")
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      cfg = _og_referral_cfg(gname)
      target = _parse_referral_bot_target(cfg.get("link") or "")
      if not target:
          return await event.answer("اول یوزرنیم یا لینک معتبر ربات را ثبت کن؛ نمونه: @amir_bot یا https://t.me/amir_bot?start=ABC123", alert=True)
      sessions = list(dict.fromkeys(og_sessions(gname)))
      if not sessions:
          return await event.answer("این ریموت سشنی ندارد.", alert=True)
      lock = _og_referral_locks.setdefault(gname, asyncio.Lock())
      if lock.locked():
          return await event.answer("عملیات Referral همین ریموت در حال اجراست.", alert=True)
      username, payload = target
      async with lock:
          await event.answer(f"در حال پردازش {len(sessions)} سشن همین ریموت...")
          done = set(cfg.get("done_sessions") or [])
          async def _start_remote_one(sess):
              meta = managed.get(sess); client = meta.get("client") if meta else None
              if not client: return sess, "آفلاین"
              if sess in done: return sess, "قبلاً موفق"
              try:
                  entity = await client.get_entity(username)
                  if not getattr(entity, "bot", False): raise ValueError("لینک متعلق به ربات نیست")
                  if payload:
                      await client(functions.messages.StartBotRequest(
                          bot=types.InputUser(int(entity.id), int(entity.access_hash)),
                          peer=types.InputPeerSelf(), random_id=random.getrandbits(63), start_param=payload))
                  else:
                      # StartBotRequest rejects an empty start_param; a plain /start
                      # message is the correct path for username-only bot links.
                      await client.send_message(entity, "/start")
                  return sess, "موفق"
              except Exception as exc:
                  return sess, f"خطا: {type(exc).__name__}: {str(exc)[:90]}"
          results = await asyncio.gather(*(_start_remote_one(x) for x in sessions))
          for sess, status in results:
              if status == "موفق": done.add(sess)
          cfg["done_sessions"] = sorted(done)
          cfg["last_results"] = {sess: status for sess, status in results}
          extractor = next((sess for sess, status in results if status in ("موفق", "قبلاً موفق") and managed.get(sess) and managed[sess].get("client")), None)
          options = []
          if extractor:
              try:
                  client = managed[extractor]["client"]; entity = await client.get_entity(username)
                  for _ in range(20):
                      options = await _referral_find_buttons(client, entity)
                      if options: break
                      await asyncio.sleep(1)
              except Exception: options = []
          cfg["extract_session"] = extractor or ""
          cfg["button_options"] = options
          cfg["last_result"] = f"موفق: {sum(x == 'موفق' for _,x in results)} | آفلاین: {sum(x == 'آفلاین' for _,x in results)} | دکمه‌ها: {len(options)}"
          save_groups()
          detail = "\n".join(f"• {sess}: {status}" for sess, status in results[:40])
          await sp_edit(event, _og_referral_text(gname) + "\n\nگزارش:\n" + detail, buttons=_og_referral_buttons(gname))

    @bot.on(events.CallbackQuery(pattern=re.compile(rb"ogref_choose_(.+)_(\d+)")))
    async def _og_referral_choose_cb(event):
      gname = event.pattern_match.group(1).decode(errors="ignore")
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      cfg = _og_referral_cfg(gname); idx = int(event.pattern_match.group(2))
      options = cfg.get("button_options") or []
      if idx < 0 or idx >= len(options):
          return await event.answer("گزینه معتبر نیست؛ دوباره استخراج کن.", alert=True)
      option = options[idx]
      try: callback_data = bytes.fromhex(option.get("data_hex", ""))
      except Exception: return await event.answer("داده دکمه معتبر نیست.", alert=True)
      link_target = _parse_referral_bot_target(cfg.get("link") or "")
      if not link_target: return await event.answer("یوزرنیم یا لینک ربات ثبت نشده است.", alert=True)
      username = link_target[0]; sessions = list(dict.fromkeys(og_sessions(gname)))
      lock = _og_referral_locks.setdefault(gname, asyncio.Lock())
      if lock.locked(): return await event.answer("عملیات همین ریموت در حال اجراست.", alert=True)
      async with lock:
          await event.answer(f"در حال انتخاب «{option.get('text','')}» روی سشن‌های همین ریموت...")
          async def _click_remote_one(sess):
              meta = managed.get(sess); client = meta.get("client") if meta else None
              if not client: return sess, "آفلاین"
              try:
                  entity = await client.get_entity(username)
                  for msg in await client.get_messages(entity, limit=30):
                      for row in getattr(getattr(msg, "reply_markup", None), "rows", []) or []:
                          for btn in getattr(row, "buttons", []) or []:
                              if getattr(btn, "data", None) and bytes(btn.data) == callback_data:
                                  await client(functions.messages.GetBotCallbackAnswerRequest(peer=entity, msg_id=msg.id, data=callback_data))
                                  return sess, "انتخاب شد"
                  return sess, "دکمه در پیام پیدا نشد"
              except Exception as exc: return sess, f"خطا: {type(exc).__name__}: {str(exc)[:80]}"
          results = await asyncio.gather(*(_click_remote_one(x) for x in sessions))
          cfg["last_result"] = f"انتخاب {option.get('text','')}: {sum(x == 'انتخاب شد' for _,x in results)}/{len(sessions)}"
          cfg["last_results"] = {sess: status for sess, status in results}
          extractor = str(cfg.get("extract_session") or ""); meta = managed.get(extractor); client = meta.get("client") if meta else None
          next_options = []
          if client:
              try:
                  entity = await client.get_entity(username)
                  for _ in range(20):
                      next_options = await _referral_find_buttons(client, entity)
                      if next_options: break
                      await asyncio.sleep(1)
              except Exception: next_options = []
          cfg["button_options"] = next_options; save_groups()
          details = "\n".join(f"• {sess}: {status}" for sess, status in results[:40])
          await sp_edit(event, _og_referral_text(gname) + "\n\nگزارش انتخاب:\n" + details, buttons=_og_referral_buttons(gname))

    def _og_repeater_cfg(gname):
      info = groups_db.setdefault(gname, {})
