    _ogfwd_locks = {}
    _ogfwd_runs = {}
    def _og_parse_decimal_time(value):
      """Parse time values with Persian/Arabic digits and decimal separators."""
      raw = str(value or "").strip()
      translation = str.maketrans({
          "۰": "0", "۱": "1", "۲": "2", "۳": "3", "۴": "4",
          "۵": "5", "۶": "6", "۷": "7", "۸": "8", "۹": "9",
          "٠": "0", "١": "1", "٢": "2", "٣": "3", "٤": "4",
          "٥": "5", "٦": "6", "٧": "7", "٨": "8", "٩": "9",
          "٫": ".", "٬": "", "،": ".", ",": ".",
      })
      return float(raw.translate(translation))

    _OG_FWD_MIN_INTERVAL = 0.1

    def _og_fwd_state(gname):
      state = groups_db.setdefault(gname, {}).setdefault("forward_attacker", {
          "source": "", "source_link": "", "source_links": [], "target": "",
          "targets": [], "target_labels": {}, "session": "", "interval": 1.0,
          "sent_pairs": [], "last_forward_ts": 0.0,
          "seq_mode": False, "seq_interval": 1.0,
      })
      state.setdefault("source", "")
      state.setdefault("source_link", "")
      state.setdefault("source_links", [])

      if not state["source_links"] and state.get("source_link"):
          state["source_links"] = [str(state["source_link"]).strip()]
      state.setdefault("target", "")
      state.setdefault("targets", [])
      if not state["targets"] and state.get("target"):
          state["targets"] = [str(state["target"])]
      if state.get("targets"):
          state["targets"] = [str(state["targets"][0])]
          state["target"] = state["targets"][0]
      state.setdefault("target_labels", {})
      state.setdefault("session", "")
      state.setdefault("sessions", [])
      if not state["sessions"] and state.get("session"):
          state["sessions"] = [str(state["session"])]
      state["sessions"] = list(dict.fromkeys(str(x) for x in state["sessions"] if str(x)))
      state["session"] = state["sessions"][0] if state["sessions"] else ""
      state.setdefault("interval", _OG_FWD_MIN_INTERVAL)
      state.setdefault("sent_pairs", [])
      state.setdefault("last_forward_ts", 0.0)
      state.setdefault("last_success_count", 0)
      state.setdefault("last_fail_count", 0)
      state.setdefault("last_attempt_count", 0)
      state.setdefault("last_source_link", "")
      state.setdefault("last_uptime_seconds", 0)
      state.setdefault("last_text_count", 0)
      state.setdefault("last_media_count", 0)
      state.setdefault("seq_mode", False)
      state.setdefault("seq_interval", 1.0)
      state.setdefault("auto_stop_hours", 0.0)
      try:
          state["auto_stop_hours"] = max(0.0, min(8760.0, float(state["auto_stop_hours"])))
      except Exception:
          state["auto_stop_hours"] = 0.0
      try:
          state["interval"] = max(_OG_FWD_MIN_INTERVAL, min(3600.0, float(state["interval"])))
      except Exception:
          state["interval"] = _OG_FWD_MIN_INTERVAL
      try:
          state["seq_interval"] = max(_OG_FWD_MIN_INTERVAL, min(3600.0, float(state["seq_interval"])))
      except Exception:
          state["seq_interval"] = 1.0
      return state

    def _og_fwd_online_sessions(gname):
      return [sess for sess in groups_db.get(gname, {}).get("sessions", [])
              if sess in managed and managed[sess].get("client")
              and managed[sess]["client"].is_connected()]

    def _og_parse_message_link(raw_link):
      import urllib.parse as _urlparse
      raw = str(raw_link or "").strip()
      parsed = _urlparse.urlparse(raw if "://" in raw else "https://" + raw)
      host = (parsed.netloc or "").lower().split(":", 1)[0]
      if host not in ("t.me", "www.t.me", "telegram.me", "www.telegram.me"):
          raise ValueError("لینک باید از نوع t.me باشد.")
      parts = [x for x in parsed.path.split("/") if x]
      if parts and parts[0] == "s":
          parts = parts[1:]
      if len(parts) == 3 and parts[0] == "c":
          try:
              return ("private", int(parts[1]), int(parts[2]))
          except ValueError:
              raise ValueError("شناسه پیام داخل لینک معتبر نیست.")
      if len(parts) == 2 and parts[0] not in ("joinchat", "addstickers"):
          try:
              return ("public", parts[0].lstrip("@"), int(parts[1]))
          except ValueError:
              pass
      raise ValueError("لینک پیام معتبر نیست؛ نمونه: https://t.me/channel/123 یا https://t.me/c/123456/789")

    def _ogfwd_format_uptime(seconds):
      total = max(0, int(seconds or 0))
      hours, rem = divmod(total, 3600)
      minutes, secs = divmod(rem, 60)
      return f"{hours:02d}:{minutes:02d}:{secs:02d}"

    def _og_fwd_panel_text(gname):
      state = _og_fwd_state(gname)
      run = _ogfwd_runs.get(gname)
      running = bool(run and run.get("task") and not run["task"].done())

      sent_count = int((run or {}).get("ok", state.get("last_success_count", 0)) or 0)
      fail_count = int((run or {}).get("fail", state.get("last_fail_count", 0)) or 0)
      text_count = int((run or {}).get("text_count", state.get("last_text_count", 0)) or 0)
      media_count = int((run or {}).get("media_count", state.get("last_media_count", 0)) or 0)

      last_uptime = int(state.get("last_uptime_seconds", 0) or 0)
      uptime_seconds = last_uptime
      if running and run.get("started_at"):
          uptime_seconds = time.monotonic() - run["started_at"]
      uptime = _ogfwd_format_uptime(uptime_seconds)

      target = str(state.get("target") or (state.get("targets") or ["—"])[0] or "—")
      active_count = int((run or {}).get("active_accounts", 0) or 0) if running else len(_og_fwd_online_sessions(gname))
      status = "🟢 فعال" if running else "🔴 متوقف"
      updated = datetime.now(IRAN_TZ).strftime("%H:%M:%S")

      return (
          f"⚔️ پنل زنده Attacker\n"
          "━━━━━━━━━━━━━━\n"
          f"👥 ریموت: {gname}\n"
          f"📊 وضعیت: {status}\n"
          f"🎯 مقصد: {target}\n"
          f"📝 متن: {text_count}  |  🖼 مدیا: {media_count}\n"
          "━━━━━━━━━━━━━━\n"
          f"📤 ارسال‌شده: {sent_count:,}\n"
          f"❌ خطا: {fail_count:,}\n"
          f"⏱ آپتایم: {uptime}\n"
          f"👤 اکانت فعال: {active_count}\n"
          "━━━━━━━━━━━━━━\n"
          f"🔄 آپدیت: {updated}"
      )

    def _og_fwd_panel_buttons(gname):
      run = _ogfwd_runs.get(gname)
      running = bool(run and run.get("task") and not run["task"].done())
      state = _og_fwd_state(gname)
      rows = [
          [Button.inline("🔗 ثبت لینک‌های منبع", f"ogfwd_setlink_{gname}".encode())],
          [Button.inline("👥 انتخاب سشن‌های آنلاین", f"ogfwd_selsess_{gname}".encode())],
          [Button.inline("📤 انتخاب یک گروه مقصد", f"ogfwd_selgrp_{gname}".encode())],
          [Button.inline(f"⏱ فاصله ارسال ({state.get('interval', 1)}s)", f"ogfwd_setinterval_{gname}".encode())],
          [Button.inline(f"⏰ خاموشی خودکار ({(str(state.get('auto_stop_hours')) + 'h') if state.get('auto_stop_hours') else 'خاموش'})", f"ogfwd_autostop_{gname}".encode())],
          [Button.inline(f"🔁 نوبتی منبع‌ها: {'✅' if state.get('seq_mode') else '❌'}", f"ogfwd_seqmode_{gname}".encode()),
           Button.inline(f"⏱ ثانیه نوبتی ({state.get('seq_interval', 1)}s)", f"ogfwd_seqinterval_{gname}".encode())],
      ]
      if running:
          rows.append([Button.inline("⏹ خاموش‌کردن فوروارد", f"ogfwd_stop_{gname}".encode())])
      else:
          rows.append([Button.inline("▶️ شروع فوروارد", f"ogfwd_start_{gname}".encode())])
      rows.extend([
          [Button.inline("🧹 پاک‌کردن لینک‌ها، مقصد و سابقه", f"ogfwd_clear_{gname}".encode())],
          [Button.inline("🔙 بازگشت به منوی ریموت", f"og_home_{gname}".encode())],
      ])
      return rows

    async def _ogfwd_refresh_live_message(chat_id, message_id, gname):
      if not message_id:
          return
      try:
          await bot.edit_message(
              chat_id,
              message_id,
              _og_fwd_panel_text(gname),
              buttons=_og_fwd_panel_buttons(gname),
          )
      except Exception as refresh_error:
          log.debug("[ogfwd:%s] live report refresh failed: %s", gname, refresh_error)

    async def _ogfwd_show_groups(event, gname, mode, page=0, already_answered=False):
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      state = _og_fwd_state(gname)
      sessions = [x for x in state.get("sessions", []) if x in _og_fwd_online_sessions(gname)]
      if not sessions:
          return await event.answer("ابتدا حداقل یک سشن آنلاین انتخاب کن.", alert=True)
      cache_key = f"ogfwd_{gname}_" + "|".join(sorted(sessions))
      try:
          cached = _atk_grp_cache.get(cache_key)
          if cached and (time.time() - cached.get("ts", 0)) < _ATK_GRP_CACHE_TTL:
              groups_list = cached.get("groups", [])
          else:
              if not already_answered:
                  await event.answer("⏳ در حال دریافت گروه‌های جوین‌شده سشن‌های انتخاب‌شده...")
              groups_list = await _fetch_joined_groups(sessions)
              _atk_grp_cache[cache_key] = {"groups": groups_list, "ts": time.time()}
          if not groups_list:
              return await sp_edit(event, "گروه جوین‌شده‌ای برای سشن‌های انتخاب‌شده پیدا نشد.",
                  buttons=[[Button.inline("🔙 بازگشت", f"ogfwd_panel_{gname}".encode())]])
          selected_target = str(state.get("target") or "")
          page_size = 35
          max_page = max(0, (len(groups_list) - 1) // page_size)
          page = max(0, min(int(page), max_page))
          rows = []
          for name, gid in groups_list[page * page_size:(page + 1) * page_size]:
              gid_s = str(gid)
              tick = "✅" if gid_s == selected_target else "▫️"
              rows.append([Button.inline(
                  f"{tick} {(name or gid_s)[:30]}",
                  f"ogfwd_setgrp_{gname}|{gid_s}".encode(),
              )])
          nav = []
          if page > 0:
              nav.append(Button.inline("⬅️ قبلی", f"ogfwd_page_{gname}|target|{page-1}".encode()))
          if page < max_page:
              nav.append(Button.inline("➡️ بعدی", f"ogfwd_page_{gname}|target|{page+1}".encode()))
          if nav:
              rows.append(nav)
          rows.append([Button.inline(f"✅ تأیید مقصد واحد: {'انتخاب شد' if selected_target else 'انتخاب نشده'}", f"ogfwd_targetdone_{gname}".encode())])
          rows.append([Button.inline("🔙 بازگشت", f"ogfwd_panel_{gname}".encode())])
          await sp_edit(event,
              f"👥 گروه‌های جوین‌شده سشن انتخاب‌شده\n"
              "فقط یک گروه مقصد انتخاب می‌شود. گروه‌های این فهرست در سشن‌های انتخاب‌شده عضو هستند.\n"
              f"مقصد فعلی: {selected_target or 'انتخاب نشده'} | صفحه {page+1} از {max_page+1}",
              buttons=rows)
          if already_answered:
              return
          if cached and (time.time() - cached.get("ts", 0)) < _ATK_GRP_CACHE_TTL:
              await event.answer()
      except Exception as exc:
          log.exception("[ogfwd:%s] failed to list joined groups", gname)
          await sp_edit(event, f"❌ دریافت گروه‌ها ناموفق بود: {str(exc)[:180]}",
              buttons=[[Button.inline("🔙 بازگشت", f"ogfwd_panel_{gname}".encode())]])

    async def _ogfwd_resolve_source(client, parsed_link):
      kind, link_ref, message_id = parsed_link
      source_entity = None
      if kind == "public":
          source_entity = await client.get_entity(link_ref)
      else:
          from telethon.tl.types import PeerChannel
          async for dialog in client.iter_dialogs():
              ent = getattr(dialog, "entity", None)
              if ent is not None and int(getattr(ent, "id", -1)) == int(link_ref):
                  source_entity = ent
                  break
          if source_entity is None:
              try:
                  source_entity = await client.get_entity(PeerChannel(int(link_ref)))
              except Exception:
                  source_entity = None
      if source_entity is None:
          raise ValueError("این سشن به کانال/گروه مبدا دسترسی ندارد یا لینک خصوصی قابل resolve نیست.")
      source_msg = await client.get_messages(source_entity, ids=int(message_id))
      if source_msg is None or getattr(source_msg, "action", None):
          raise ValueError("پیام لینک‌شده پیدا نشد یا قابل فوروارد نیست.")
      return source_msg

    async def _ogfwd_run_batch(gname, chat_id, sessions, links, target, interval):
      state = _og_fwd_state(gname)
      ok = fail = attempts = 0
      details = []
      source_link = ""
      started_at = time.monotonic()
      stop_reason = ""
      try:
          online = _og_fwd_online_sessions(gname)
          sessions = list(dict.fromkeys(str(sess) for sess in sessions if str(sess) in online))
          links = list(dict.fromkeys(str(link).strip() for link in links if str(link).strip()))
          if not sessions:
              raise RuntimeError("هیچ سشن آنلاینی انتخاب نشده است.")
          if not links:
              raise RuntimeError("لینک منبعی ثبت نشده است.")

          # Resolve every configured source per session once; this allows genuine
          # per-round random selection and a full round-robin rotation without a link cap.
          session_clients = []
          for sess in sessions:
              meta = managed.get(sess)
              client = meta.get("client") if isinstance(meta, dict) else None
              if client is None or not client.is_connected():
                  details.append(f"⚠️ سشن {sess} در زمان آماده‌سازی آفلاین شد.")
                  continue
              try:
                  target_peer = await client.get_input_entity(int(target))
              except Exception as target_exc:
                  details.append(f"⚠️ مقصد در سشن {sess} قابل دسترسی نیست: {str(target_exc)[:100]}")
                  continue
              prepared_sources = []
              for link in links:
                  try:
                      parsed_link = _og_parse_message_link(link)
                      source_msg = await _ogfwd_resolve_source(client, parsed_link)
                      prepared_sources.append((link, source_msg))
                  except Exception as source_exc:
                      details.append(f"⚠️ منبع در سشن {sess} قابل دسترسی نیست: {link[:45]} — {str(source_exc)[:75]}")
              if prepared_sources:
                  session_clients.append({
                      "session": sess,
                      "client": client,
                      "target_peer": target_peer,
                      "sources": prepared_sources,
                      "seq_offset": random.randrange(len(prepared_sources)),
                  })

          if not session_clients:
              raise RuntimeError("هیچ‌کدام از سشن‌های انتخاب‌شده به مقصد و لینک‌های منبع دسترسی ندارند.")

          # Count each configured source link once (not once per account).
          source_types = {}
          for item in session_clients:
              for source_url, source_msg in item["sources"]:
                  source_types.setdefault(str(source_url), bool(getattr(source_msg, "media", None)))
          media_count = sum(1 for has_media in source_types.values() if has_media)
          text_count = sum(1 for has_media in source_types.values() if not has_media)
          state["last_text_count"] = text_count
          state["last_media_count"] = media_count

          state["last_success_count"] = 0
          state["last_fail_count"] = 0
          state["last_attempt_count"] = 0
          state["last_source_link"] = ""
          save_groups()
          current_run = _ogfwd_runs.get(gname)
          if current_run is not None:
              current_run.update({"ok": 0, "fail": 0, "attempts": 0,
                                  "started_at": started_at,
                                  "text_count": text_count,
                                  "media_count": media_count,
                                  "active_accounts": len(session_clients)})

          live_message = await sp(
              chat_id,
              _og_fwd_panel_text(gname),
              buttons=_og_fwd_panel_buttons(gname),
          )
          live_message_id = getattr(live_message, "id", None) if live_message else None
          current_run = _ogfwd_runs.get(gname)
          if current_run is not None:
              current_run["message_id"] = live_message_id
          last_report_update = time.monotonic()

          while True:
              current_run = _ogfwd_runs.get(gname)
              if not current_run or current_run.get("stop"):
                  stop_reason = "با دکمه توقف متوقف شد"
                  break

              auto_stop_hours = max(0.0, float(_og_fwd_state(gname).get("auto_stop_hours", 0.0) or 0.0))
              elapsed = time.monotonic() - started_at
              if auto_stop_hours > 0 and elapsed >= auto_stop_hours * 3600:
                  stop_reason = "به‌دلیل فعال‌شدن خاموشی خودکار متوقف شد"
                  break

              live_state = _og_fwd_state(gname)
              seq_mode = bool(live_state.get("seq_mode", False))
              seq_interval = max(_OG_FWD_MIN_INTERVAL, float(live_state.get("seq_interval", 1.0)))
              seq_round = int(elapsed // seq_interval)

              round_attempts = 0

              async def _send_for_session(item):
                  nonlocal attempts, ok, fail, source_link, round_attempts
                  active_run = _ogfwd_runs.get(gname)
                  if not active_run or active_run.get("stop"):
                      return False
                  prepared = item["sources"]
                  if seq_mode:
                      source_slot = (item["seq_offset"] + seq_round) % len(prepared)
                      selected_link, source_msg = prepared[source_slot]
                  else:
                      selected_link, source_msg = random.choice(prepared)
                  attempts += 1
                  round_attempts += 1
                  source_link = selected_link or source_link
                  try:
                      await item["client"].forward_messages(item["target_peer"], source_msg)
                      ok += 1
                      details.append(f"✅ ارسال موفق {ok} | سشن {item['session']} | منبع {selected_link}")
                  except asyncio.CancelledError:
                      raise
                  except Exception as exc:
                      fail += 1
                      details.append(f"❌ تلاش {attempts} | سشن {item['session']} | {str(exc)[:100]}")
                  if len(details) > 12:
                      del details[:-12]
                  state["last_success_count"] = ok
                  state["last_fail_count"] = fail
                  state["last_attempt_count"] = attempts
                  state["last_source_link"] = source_link
                  active_run = _ogfwd_runs.get(gname)
                  if active_run is not None:
                      active_run.update({"ok": ok, "fail": fail, "attempts": attempts,
                                         "started_at": started_at})
                  return True

              # Each selected session sends independently in parallel in this round.
              results = await asyncio.gather(
                  *(_send_for_session(item) for item in session_clients),
                  return_exceptions=True,
              )
              made_attempt = round_attempts > 0
              for result in results:
                  if isinstance(result, BaseException):
                      if isinstance(result, asyncio.CancelledError):
                          raise result
                      fail += 1
                      attempts += 1
                      details.append(f"❌ خطای اجرای هم‌زمان: {str(result)[:100]}")
                      made_attempt = True

              state["last_success_count"] = ok
              state["last_fail_count"] = fail
              state["last_attempt_count"] = attempts
              state["last_source_link"] = source_link
              current_run = _ogfwd_runs.get(gname)
              if current_run is not None:
                  current_run.update({"ok": ok, "fail": fail, "attempts": attempts,
                                      "started_at": started_at,
                                      "active_accounts": sum(1 for item in session_clients
                                                             if item["client"].is_connected())})
              save_groups()
              if time.monotonic() - last_report_update >= 5.0:
                  await _ogfwd_refresh_live_message(chat_id, live_message_id, gname)
                  last_report_update = time.monotonic()
              if not made_attempt:
                  stop_reason = "همهٔ سشن‌ها متوقف شدند"
                  break

              wait_left = max(_OG_FWD_MIN_INTERVAL, float(interval))
              while wait_left > 0:
                  current_run = _ogfwd_runs.get(gname)
                  if not current_run or current_run.get("stop"):
                      stop_reason = "با دکمه توقف متوقف شد"
                      break
                  live_auto_stop = max(0.0, float(_og_fwd_state(gname).get("auto_stop_hours", 0.0) or 0.0))
                  if live_auto_stop and time.monotonic() - started_at >= live_auto_stop * 3600:
                      stop_reason = "به‌دلیل فعال‌شدن خاموشی خودکار متوقف شد"
                      break
                  if time.monotonic() - last_report_update >= 5.0:
                      await _ogfwd_refresh_live_message(chat_id, live_message_id, gname)
                      last_report_update = time.monotonic()
                  step = min(0.25, wait_left)
                  await asyncio.sleep(step)
                  wait_left -= step
              if stop_reason:
                  break

          uptime_seconds = time.monotonic() - started_at
          state["last_uptime_seconds"] = int(uptime_seconds)
          state["last_success_count"] = ok
          state["last_fail_count"] = fail
          state["last_attempt_count"] = attempts
          state["last_source_link"] = source_link
          save_groups()
          current_run = _ogfwd_runs.get(gname)
          if current_run and current_run.get("task") is asyncio.current_task():
              _ogfwd_runs.pop(gname, None)
          await _ogfwd_refresh_live_message(chat_id, live_message_id, gname)
          if not live_message_id:
              await sp(chat_id, _og_fwd_panel_text(gname), buttons=_og_fwd_panel_buttons(gname))
      except asyncio.CancelledError:
          stop_reason = "با درخواست توقف فوری لغو شد"
          uptime_seconds = time.monotonic() - started_at
          state["last_uptime_seconds"] = int(uptime_seconds)
          state["last_success_count"] = ok
          state["last_fail_count"] = fail
          state["last_attempt_count"] = attempts
          save_groups()
          current_run = _ogfwd_runs.get(gname)
          live_message_id = current_run.get("message_id") if current_run else None
          if current_run and current_run.get("task") is asyncio.current_task():
              _ogfwd_runs.pop(gname, None)
          try:
              await _ogfwd_refresh_live_message(chat_id, live_message_id, gname)
              if not live_message_id:
                  await sp(chat_id, _og_fwd_panel_text(gname), buttons=_og_fwd_panel_buttons(gname))
          except Exception:
              log.warning("[ogfwd:%s] unable to update cancellation report", gname)
      except Exception as exc:
          log.exception("[ogfwd:%s] batch failed", gname)
          state["last_uptime_seconds"] = int(time.monotonic() - started_at)
          state["last_success_count"] = ok
          state["last_fail_count"] = fail
          state["last_attempt_count"] = attempts
          save_groups()
          current_run = _ogfwd_runs.get(gname)
          live_message_id = current_run.get("message_id") if current_run else None
          if current_run and current_run.get("task") is asyncio.current_task():
              _ogfwd_runs.pop(gname, None)
          await _ogfwd_refresh_live_message(chat_id, live_message_id, gname)
          if not live_message_id:
              await sp(chat_id, _og_fwd_panel_text(gname), buttons=_og_fwd_panel_buttons(gname))
      finally:
          current_run = _ogfwd_runs.get(gname)
          if current_run and current_run.get("task") is asyncio.current_task():
              _ogfwd_runs.pop(gname, None)
          save_groups()

