    @bot.on(events.CallbackQuery(pattern=re.compile(rb"ogfwd_setgrp_([^|]+)\|(.+)")))
    async def _og_forward_set_group_cb(event):
      gname = event.pattern_match.group(1).decode(errors="ignore")
      gid = event.pattern_match.group(2).decode(errors="ignore")
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      state = _og_fwd_state(gname)
      current = str(state.get("target") or "")
      if current == gid:
          state["target"] = ""
          state["targets"] = []
          state.setdefault("target_labels", {}).pop(gid, None)
          await event.answer("مقصد پاک شد.")
      else:
          state["target"] = gid
          state["targets"] = [gid]
          try:
              sessions = [x for x in state.get("sessions", []) if x in _og_fwd_online_sessions(gname)]
              cache_key = f"ogfwd_{gname}_" + "|".join(sorted(sessions))
              cache = _atk_grp_cache.get(cache_key, {})
              found = cache.get("groups", [])
              label = next((name for name, group_id in found if str(group_id) == gid), gid)
              state.setdefault("target_labels", {})[gid] = str(label)
          except Exception:
              state.setdefault("target_labels", {})[gid] = gid
          await event.answer("یک گروه مقصد انتخاب شد.")
      save_groups()
      await _ogfwd_show_groups(event, gname, "target", 0, already_answered=True)

