    @bot.on(events.CallbackQuery(pattern=re.compile(rb"ogfwd_start_(.+)")))
    async def _og_forward_start_batch_cb(event):
      gname = event.pattern_match.group(1).decode(errors="ignore")
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      state = _og_fwd_state(gname)
      links = [str(x).strip() for x in state.get("source_links", []) if str(x).strip()]
      sessions = [str(x) for x in state.get("sessions", [])]
      targets = [str(x) for x in state.get("targets", [])[:1]]
      target = targets[0] if targets else str(state.get("target") or "")
      if not links or not sessions or not target:
          return await event.answer("ابتدا لینک‌ها، حداقل یک سشن و یک گروه مقصد را انتخاب کن.", alert=True)
      try:
          for link in links:
              _og_parse_message_link(link)
      except ValueError as exc:
          return await event.answer(str(exc), alert=True)
      online = _og_fwd_online_sessions(gname)
      sessions = [sess for sess in sessions if sess in online]
      if not sessions:
          return await event.answer("هیچ‌کدام از سشن‌های انتخاب‌شده آنلاین نیستند.", alert=True)
      existing = _ogfwd_runs.get(gname)
      if existing and existing.get("task") and not existing["task"].done():
          return await event.answer("یک بسته در حال اجراست؛ ابتدا آن را متوقف کن.", alert=True)
      interval = max(_OG_FWD_MIN_INTERVAL, float(state.get("interval", _OG_FWD_MIN_INTERVAL)))
      await event.answer("فوروارد در حال شروع است")
      await sp_edit(event, f"⏳ آماده‌سازی {len(sessions)} سشن انتخاب‌شده؛ اجرا تا توقف دستی یا خاموشی خودکار ادامه دارد...", buttons=[[Button.inline("⏹ توقف فوری", f"ogfwd_stop_{gname}".encode())]])
      task = asyncio.create_task(_ogfwd_run_batch(gname, event.chat_id, sessions, links, target, interval))
      _ogfwd_runs[gname] = {"task": task, "stop": False, "started_at": time.monotonic(),
                            "ok": 0, "fail": 0, "attempts": 0}

