    async def _og_tabchi_resolve_source(client, link: str):
      parsed = _parse_telegram_post_link(link)
      if not parsed:
          raise ValueError("لینک پست معتبر نیست؛ لینک t.me/channel/123 یا t.me/c/123/123 بفرست.")
      if parsed["kind"] == "public":
          source_entity = await client.get_entity("@" + parsed["username"])
      else:
          source_entity = await _resolve_autoseen_entity(client, "-100" + str(parsed["channel_id"]))
      msg = await client.get_messages(source_entity, ids=int(parsed["message_id"]))
      if not msg:
          raise ValueError("پست پیدا نشد یا سشن به کانال مبدأ دسترسی ندارد.")
      return msg

