      if not sess or sess not in groups_db.get(gname, {}).get("sessions", []):
          return await event.answer("ابتدا سشن تبچی را انتخاب کن.", alert=True)
      meta = managed.get(sess)
      client = meta.get("client") if isinstance(meta, dict) else None
      try:
          online = bool(client and (not hasattr(client, "is_connected") or client.is_connected()))
      except Exception:
          online = False
      if not online:
          return await event.answer("سشن انتخاب‌شدهٔ تبچی آنلاین نیست.", alert=True)
      cfg["digi_join_session"] = sess
      save_groups()
