    async def _og_tabchi_forward_batch(gname: str, chat_id: int):
      cfg = _og_tabchi_cfg(gname)
      sess = cfg.get("session", "")
      client = _og_tabchi_client(gname)
      if not client:
          raise RuntimeError("سشن این ریموت آنلاین نیست.")
      source_msg = await _og_tabchi_resolve_source(client, cfg.get("source_link", ""))
      eligible = await _og_tabchi_admin_groups(client)
      if not eligible:
          await sp(chat_id, "گروه جوین‌شده‌ای که ارسال پیام در آن مجاز باشد پیدا نشد.",
                   buttons=[[Button.inline("📨 بازگشت به تبچی", f"og_tabchi_{gname}".encode())]])
          return

      destinations = random.sample(eligible, min(5, len(eligible)))
      run = _og_tabchi_runs.get(gname, {})
      ok = fail = skipped = 0
      details = []
      for index, dest in enumerate(destinations):
          if not run.get("running"):
              break
          try:
              raw = str(dest).strip()
              if re.fullmatch(r"-100\d+", raw):
                  dest_entity = await _resolve_autoseen_entity(client, raw)
              else:
                  dest_entity = await client.get_entity(int(raw) if re.fullmatch(r"-?\d+", raw) else raw)
              is_group = isinstance(dest_entity, types.Chat) or (
                  isinstance(dest_entity, types.Channel) and bool(getattr(dest_entity, "megagroup", False))
              )
              banned = getattr(dest_entity, "banned_rights", None) or getattr(dest_entity, "default_banned_rights", None)
              can_send = banned is None or not bool(getattr(banned, "send_messages", False))
              if not is_group or not can_send:
                  skipped += 1
                  details.append(f"⏭ {dest}: گروه نیست یا اجازه ارسال پیام ندارد")
              else:
                  await client.forward_messages(dest_entity, source_msg)
                  ok += 1
                  details.append(f"✅ {getattr(dest_entity, 'title', dest)}")
          except Exception as exc:
              fail += 1
              details.append(f"❌ {dest}: {str(exc)[:90]}")
          if index < len(destinations) - 1 and run.get("running"):
              await asyncio.sleep(2)

      interval_minutes = max(1800, int(cfg.get("interval", 1800))) // 60
      summary = (
          f"گزارش نوبت تبچی — ریموت {gname}\n"
          f"سشن: {sess}\n"
          f"انتخاب‌شده: {len(destinations)} | موفق: {ok} | ناموفق: {fail} | ردشده: {skipped}\n"
          f"نوبت بعدی پس از {interval_minutes} دقیقه\n\n"
          + "\n".join(details[:5])
      )
      await sp(chat_id, summary, buttons=[[Button.inline("📨 بازگشت به تبچی", f"og_tabchi_{gname}".encode())]])

    async def _og_tabchi_execute(gname: str, chat_id: int):
      run = _og_tabchi_runs.get(gname, {})
      while run.get("running"):
          try:
              await _og_tabchi_forward_batch(gname, chat_id)
          except asyncio.CancelledError:
              raise
          except Exception as exc:
              log.exception("[og-tabchi:%s] scheduled batch failed: %s", gname, exc)
              try:
                  await sp(
                      chat_id,
                      f"خطای این نوبت تبچی: {str(exc)[:160]}\nتبچی روشن می‌ماند و در نوبت بعدی دوباره تلاش می‌کند.",
                      buttons=[[Button.inline("📨 بازگشت به تبچی", f"og_tabchi_{gname}".encode())]],
                  )
              except Exception:
                  pass
          if not run.get("running"):
              break
          cfg = _og_tabchi_cfg(gname)
          interval = max(1800, min(604800, int(cfg.get("interval", 1800))))
          await asyncio.sleep(interval)

    async def _og_tabchi_runner(gname: str, chat_id: int):
      run = _og_tabchi_runs.get(gname, {})
      try:
          await _og_tabchi_execute(gname, chat_id)
      except asyncio.CancelledError:
          pass
      except Exception as exc:
          log.exception("[og-tabchi:%s] runner failed: %s", gname, exc)
          try:
              await sp(chat_id, f"خطای اجرای تبچی: {str(exc)[:160]}")
          except Exception:
              pass
      finally:
          run["running"] = False
          if _og_tabchi_tasks.get(gname) is asyncio.current_task():
              _og_tabchi_tasks.pop(gname, None)
          try:
              await sp_edit(
                  type("TabchiPanelEvent", (), {"chat_id": chat_id})(),
                  _og_tabchi_text(gname),
                  buttons=_og_tabchi_buttons(gname),
              )
          except Exception:
              pass

    @bot.on(events.CallbackQuery(pattern=re.compile(rb"og_tabchi_send_(.+)")))
    async def _og_tabchi_send_cb(event):
      gname = event.pattern_match.group(1).decode(errors="ignore")
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      run = _og_tabchi_runs.get(gname, {})
      if run.get("running"):
          run["running"] = False
          task = _og_tabchi_tasks.get(gname)
          if task and not task.done():
              task.cancel()
          await event.answer("تبچی خاموش شد؛ ارسال دوره‌ای متوقف می‌شود.")
          await sp_edit(event, _og_tabchi_text(gname), buttons=_og_tabchi_buttons(gname))
          return

      cfg = _og_tabchi_cfg(gname)
      client = _og_tabchi_client(gname)
      if not client:
          return await event.answer("سشن انتخابی این ریموت آنلاین نیست.", alert=True)
      if not cfg.get("source_link"):
          return await event.answer("ابتدا لینک پیام را ثبت کن.", alert=True)
      try:
          eligible = await _og_tabchi_admin_groups(client)
          if not eligible:
              return await event.answer(
                  "هیچ گروه جوین‌شده‌ای با اجازه ارسال پیام پیدا نشد.",
                  alert=True,
              )
      except Exception as exc:
          log.exception("[og-tabchi:%s] eligible-group discovery failed: %s", gname, exc)
          return await event.answer("خطا در شناسایی گروه‌های مدیریتی؛ لاگ را بررسی کن.", alert=True)

      try:
          await _og_tabchi_resolve_source(client, cfg.get("source_link", ""))
      except Exception as exc:
          return await event.answer(f"دسترسی به پیام مبدأ ممکن نیست: {str(exc)[:100]}", alert=True)

      interval = max(1800, min(604800, int(cfg.get("interval", 1800))))
      cfg["interval"] = interval
      save_groups()
      _og_tabchi_runs[gname] = {
          "running": True,
          "chat_id": event.chat_id,
          "sender_id": event.sender_id,
      }
      task = asyncio.create_task(_og_tabchi_runner(gname, event.chat_id))
      _og_tabchi_tasks[gname] = task
      await event.answer(f"تبچی روشن شد؛ {len(eligible)} گروه جوین‌شده با اجازه ارسال پیدا شد.")
      await sp_edit(event, _og_tabchi_text(gname), buttons=_og_tabchi_buttons(gname))

