    @bot.on(events.CallbackQuery(pattern=re.compile(rb"og_autoseen_hist_(yes|no)_(.+)")))
    async def _og_autoseen_history_choice_cb(event):
      choice = event.pattern_match.group(1).decode(); gname = event.pattern_match.group(2).decode()
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      # Resolve the pending choice by its explicit remote scope. The legacy
      # integer-key lookup follows the user's last active remote and can point
      # at another remote when two panels are used concurrently.
      pend = pending_group_selection.get(("remote", str(gname), event.sender_id))
      if pend is None and event.sender_id != OWNER_ID:
          pend = pending_group_selection.get(("remote", str(gname), OWNER_ID))
      if not isinstance(pend, dict) or pend.get("og_step") != "autoseen_history_choice" or str(pend.get("og_gname")) != str(gname):
          return await event.answer("درخواست منقضی شده؛ دوباره کانال را اضافه کنید.", alert=True)
      channel = pend.get("og_channel", "")
      pending_group_selection.pop(("remote", str(gname), event.sender_id), None)
      pending_group_selection.pop(("remote", str(gname), OWNER_ID), None)
      state = _og_autoseen_state(gname)
      sessions = _automation_sessions(gname, state)
      state.setdefault("new_only_channels", [])
      if choice == "yes":
          state["new_only_channels"] = [x for x in state["new_only_channels"] if str(x) != str(channel)]
      else:
          if str(channel) not in state["new_only_channels"]:
              state["new_only_channels"].append(str(channel))
      note = "\nاز این پس پست‌های جدید ویو می‌شوند."
      callback_answered = False
      if choice == "yes" and sessions:
          # A history scan can take longer than Telegram's callback-query
          # deadline. Acknowledge immediately so the inline button never
          # appears stuck while the requested history is being processed.
          await event.answer("درخواست ویوی تاریخچه ثبت شد؛ پردازش شروع می‌شود.")
          callback_answered = True
          completed = 0
          total_posts = 0
          failures = []
          for sess, client in sessions:
              try:
                  entity = await _resolve_autoseen_entity(client, channel)
                  batch = []
                  latest_id = 0
                  session_posts = 0
                  async for message in client.iter_messages(entity, reverse=True):
                      msg_id = int(getattr(message, "id", 0) or 0)
                      if msg_id <= 0:
                          continue
                      latest_id = max(latest_id, msg_id)

                      if getattr(message, "views", None) is not None:
                          batch.append(msg_id)
                      if len(batch) >= 100:
                          try:
                              await client(functions.messages.GetMessagesViewsRequest(
                                  peer=entity, id=batch, increment=True
                              ))
                          except RPCError as exc:
                              if "CHAT_NOT_MODIFIED" not in str(exc).upper():
                                  raise
                          session_posts += len(batch)
                          _store_auto_cursor(
                              gname, "autoseen",
                              _session_cursor_key(str(channel), sess), batch[-1]
                          )
                          batch = []
                          await asyncio.sleep(0.2)
                  if batch:
                      try:
                          await client(functions.messages.GetMessagesViewsRequest(
                              peer=entity, id=batch, increment=True
                          ))
                      except RPCError as exc:
                          if "CHAT_NOT_MODIFIED" not in str(exc).upper():
                              raise
                      session_posts += len(batch)
                  if latest_id:
                      _store_auto_cursor(
                          gname, "autoseen",
                          _session_cursor_key(str(channel), sess), latest_id
                      )
                  total_posts = max(total_posts, session_posts)
                  completed += 1
              except Exception as exc:
                  failures.append(f"{sess}: {str(exc)[:70]}")
          if completed:
              note = (f"\nدرخواست ویوی {total_posts} پستِ دارای شمارنده برای "
                      f"{completed} سشن از {len(sessions)} سشن ارسال شد؛ پست‌های جدید هم ویو می‌شوند.")
          if failures:
              note += "\nخطا: " + " | ".join(failures[:3])
      elif choice == "yes":
          await event.answer("هیچ سشن آنلاینی در دسترس نیست؛ تاریخچه ویو نشد.")
          callback_answered = True
          note = "\nهیچ سشن آنلاینی در دسترس نبود؛ ویوی تاریخچه انجام نشد."
      else:
          await event.answer("تنظیم شد؛ فقط پست‌های جدید ویو می‌شوند.")
          callback_answered = True
          for sess, client in sessions:
              try:
                  entity = await _resolve_autoseen_entity(client, channel)
                  latest = await client.get_messages(entity, limit=1)
                  if latest:
                      _store_auto_cursor(gname, "autoseen", _session_cursor_key(str(channel), sess), int(latest[0].id))
              except Exception as exc:
                  log.warning("[autoseen:%s:%s] failed to set new-only view baseline for %s: %s", gname, sess, channel, exc)
      save_groups()
      if not callback_answered:
          await event.answer("تنظیم ذخیره شد")
      await sp_edit(event, f"کانال {channel} ثبت شد.{note}", buttons=[[Button.inline("👁 ویو خودکار", f"og_autoseen_{gname}".encode())]])

    @bot.on(events.CallbackQuery(pattern=re.compile(rb"og_autoseen_del_(.+)\|(\d+)")))
    async def _og_autoseen_delete_cb(event):
      gname = event.pattern_match.group(1).decode()
      idx = int(event.pattern_match.group(2).decode())
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      state = _og_autoseen_state(gname)
      channels = state.get("channels", [])
      deleted = 0 <= idx < len(channels)
      if deleted:
          removed_channel = channels.pop(idx)
          _autoseen_last_ids.setdefault(gname, {}).pop(str(removed_channel), None)
          _og_autoseen_state(gname).setdefault("last_ids", {}).pop(str(removed_channel), None)
          _og_autoseen_state(gname).setdefault("new_only_channels", [])[:] = [
              x for x in _og_autoseen_state(gname).get("new_only_channels", []) if str(x) != str(removed_channel)
          ]
          save_groups()
      await event.answer("کانال حذف شد" if deleted else "موردی پیدا نشد")
      await sp_edit(event, _og_autoseen_text(gname), buttons=_og_autoseen_buttons(gname))

