    @bot.on(events.CallbackQuery(pattern=re.compile(rb"^og_idreact_mode_(all|custom)_(.+)$")))
    async def _og_idreact_mode_cb(event):
      mode = event.pattern_match.group(1).decode(errors="ignore")
      gname = event.pattern_match.group(2).decode(errors="ignore")
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      pending = pending_group_selection.get(event.sender_id) or pending_group_selection.get(OWNER_ID, {})
      if pending.get("og_step") != "autoreact_global_user_mode" or pending.get("og_gname") != gname:
          return await event.answer("این مرحله منقضی شده؛ دوباره آیدی را ثبت کن.", alert=True)
      sender_id = int(pending.get("og_sender_id", 0) or 0)
      if sender_id <= 0:
          return await event.answer("آیدی معتبر نیست؛ دوباره تلاش کن.", alert=True)
      if mode == "custom":
          next_pending = {"og_step": "autoreact_global_user_emojis", "og_gname": gname,
                          "og_sender_id": sender_id}
          pending_group_selection[event.sender_id] = next_pending
          pending_group_selection[OWNER_ID] = dict(next_pending)
          await sp_edit(event, "۱ تا ۱۲ ایموجی معمولی بفرست؛ با فاصله یا ویرگول جدا کن. هر سشن برای هر پیام، جداگانه از ایموجی‌های انتخابی که در همان گروه مجاز باشند یکی را تصادفی انتخاب می‌کند.")
          await event.answer()
          return

      state = _og_autoreact_state(gname)
      state["rules"] = [
          item for item in state.get("rules", [])
          if not (isinstance(item, dict) and item.get("sender_id") is not None
                  and str(item.get("sender_id")) == str(sender_id))
      ]
      state["rules"].append({"sender_id": sender_id, "all_groups": True,
                             "auto_allowed": True, "emojis": []})
      state["group_reaction_enabled"] = True
      save_groups()
      pending_group_selection.pop(event.sender_id, None)
      pending_group_selection.pop(OWNER_ID, None)
      _ensure_idreact_loop(gname)
      await sp_edit(event, f"✅ آیدی {sender_id} ثبت و فعال شد.\nتمام پیام‌های این کاربر در همهٔ گروه‌های سشن‌های آنلاین بررسی می‌شود؛ هر سشن برای هر پیام یک واکنش تصادفی از کل فهرست مجاز همان گروه انتخاب می‌کند.",
                    buttons=_og_idreact_buttons(gname))
      await event.answer("حالت تمام واکنش‌های مجاز فعال شد")

