    @bot.on(events.CallbackQuery(pattern=re.compile(rb"^og_idreact_clr_(.+)$")))
    async def _og_idreact_clear_cb(event):
      gname = event.pattern_match.group(1).decode(errors="ignore")
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      state = _og_autoreact_state(gname)
      old_rules = [r for r in state.get("rules", []) if isinstance(r, dict) and r.get("sender_id") is not None]
      state["rules"] = [r for r in state.get("rules", []) if not (isinstance(r, dict) and r.get("sender_id") is not None)]
      state["group_reaction_enabled"] = False
      for rule in old_rules:
          channel = str(rule.get("channel", ""))
          for key in list(_autoreact_last_ids.get(gname, {})):
              if key == channel or key.startswith(channel + "::session::"):
                  _autoreact_last_ids[gname].pop(key, None)
                  state.get("last_ids", {}).pop(key, None)
      save_groups()
      _stop_idreact_loop(gname)
      await event.answer("قوانین ری‌اکشن آیدی پاک شد")
      await sp_edit(event, _og_idreact_text(gname), buttons=_og_idreact_buttons(gname))

