    @bot.on(events.CallbackQuery(pattern=re.compile(rb"og_autoreact_post_run_(.+)")))
    async def _og_autoreact_post_run_cb(event):
      gname = event.pattern_match.group(1).decode(errors="ignore")
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      cfg = groups_db.get(gname, {}).get("autoreact_post", {})
      if not isinstance(cfg, dict) or not cfg.get("link") or not cfg.get("emojis"):
          return await event.answer("ابتدا لینک پست و ایموجی‌ها را ثبت کن.", alert=True)
      post_state = _og_autoreact_state(gname)
      sessions = _automation_sessions(gname, post_state)
      if not sessions:
          return await event.answer("سشن آنلاین در دسترس نیست.", alert=True)
      parsed = _parse_telegram_post_link(cfg.get("link", ""))
      if not parsed:
          return await event.answer("لینک ذخیره‌شده معتبر نیست؛ دوباره ثبتش کن.", alert=True)
      try:
          if parsed["kind"] == "private":
              entity = await client.get_entity(types.PeerChannel(parsed["channel_id"]))
          else:
              entity = await client.get_entity("@" + parsed["username"])
          msg = await client.get_messages(entity, ids=parsed["message_id"])
          if not msg:
              raise ValueError("پست پیدا نشد یا سشن به آن دسترسی ندارد")
          from telethon.tl.functions.messages import SendReactionRequest
          from telethon.tl.types import ReactionEmoji
          chosen = random.choice(cfg["emojis"])
          await client(SendReactionRequest(
              peer=entity, msg_id=parsed["message_id"],
              reaction=[ReactionEmoji(emoticon=chosen)]
          ))
          await event.answer(f"ری‌اکشن {chosen} با سشن {sess} ثبت شد.", alert=True)
      except Exception as exc:
          await event.answer(f"اجرای ری‌اکشن ناموفق بود: {str(exc)[:120]}", alert=True)

