    @bot.on(events.CallbackQuery(pattern=re.compile(rb"og_autoreact_hist_(yes|no)_(.+)")))
    async def _og_autoreact_history_choice_cb(event):
      choice = event.pattern_match.group(1).decode()
      gname = event.pattern_match.group(2).decode()
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)

      async def _edit_history_choice_panel(text, buttons=None):
          """Edit the exact message whose history-choice button was pressed."""
          chat_id = event.chat_id
          message_id = getattr(event, "message_id", None)
          try:
              plain, ents = _apply_custom_emoji(text, parse_mode="html")
              if message_id:
                  await bot.edit_message(
                      chat_id, message_id, plain,
                      formatting_entities=ents, buttons=buttons,
                  )
                  panel_msg_id[chat_id] = message_id
                  return
          except Exception as edit_exc:
              log.warning(
                  "[autoreact-history-panel] exact edit failed chat_id=%s message_id=%s: %s",
                  chat_id, message_id, edit_exc,
              )
          try:
              msg = await bot.send_message(chat_id, text, buttons=buttons)
              if msg:
                  panel_msg_id[chat_id] = msg.id
          except Exception:
              log.exception("[autoreact-history-panel] could not send replacement panel chat_id=%s", chat_id)

      # Keep history-choice callbacks tied to the remote that issued them;
      # another open remote panel must not replace this pending selection.
      pend = pending_group_selection.get(("remote", str(gname), event.sender_id))
      if pend is None and event.sender_id != OWNER_ID:
          pend = pending_group_selection.get(("remote", str(gname), OWNER_ID))
      if not isinstance(pend, dict) or pend.get("og_step") != "autoreact_history_choice" or str(pend.get("og_gname")) != str(gname):
          return await event.answer("درخواست منقضی شده؛ دوباره قانون را بسازید.", alert=True)
      channel = pend.get("og_channel", "")
      emojis = pend.get("og_emojis", [])
      auto_allowed = bool(pend.get("og_auto_allowed", False))
      state = _og_autoreact_state(gname)
      state["rules"] = [r for r in state.get("rules", []) if not isinstance(r, dict) or r.get("channel") != channel]
      state.setdefault("last_ids", {}).pop(str(channel), None)
      _autoreact_last_ids.setdefault(gname, {}).pop(str(channel), None)
      if len(state["rules"]) >= 50:
          return await event.answer("حداکثر ۵۰ قانون برای هر ریموت", alert=True)
      state["rules"].append({"channel": channel, "emojis": emojis, "auto_allowed": auto_allowed, "history": choice == "yes"})
      pending_group_selection.pop(("remote", str(gname), event.sender_id), None)
      pending_group_selection.pop(("remote", str(gname), OWNER_ID), None)
      _autoreact_last_ids.setdefault(gname, {}).pop(str(channel), None)
      save_groups()
      note = "\nاز این پس فقط پست‌های جدید بررسی می‌شوند."
      callback_answered = False

      if choice == "yes":
          sessions = _automation_sessions(gname, state)
          if not sessions:
              await event.answer("سشن آنلاین در دسترس نیست؛ تاریخچه پردازش نشد.")
              callback_answered = True
              note = "\nسشن آنلاین در دسترس نبود؛ تاریخچه پردازش نشد."
          else:
              await event.answer("پردازش تاریخچه شروع شد؛ وضعیت و درصد در پنل نمایش داده می‌شود.")
              callback_answered = True

              progress = {
                  "processed": 0,
                  "total": 0,
                  "total_per_session": None,
                  "exact_total": True,
                  "session_index": 0,
                  "status": "در حال آماده‌سازی شمارندهٔ پست‌ها",
              }
              last_progress_edit = 0.0

              def _history_progress_text(status_override=None):
                  total = int(progress.get("total", 0) or 0)
                  processed = int(progress.get("processed", 0) or 0)
                  if total > 0:
                      percent = max(0, min(100, int((processed * 100) / total)))
                      total_label = f"{total:,}" + ("" if progress.get("exact_total") else " (تخمینی)")
                  else:
                      percent = 0
                      total_label = "در حال برآورد"
                  filled = min(20, max(0, int(percent / 5)))
                  bar = "█" * filled + "░" * (20 - filled)
                  session_index = int(progress.get("session_index", 0) or 0)
                  return (
                      "📊 پیشرفت پردازش تاریخچه\n"
                      "━━━━━━━━━━━━━━━━━━━━\n"
                      f"کانال: {channel}\n"
                      f"وضعیت: {status_override or progress.get('status', 'در حال پردازش')}\n"
                      f"سشن: {session_index}/{len(sessions)}\n"
                      f"پست‌های بررسی‌شده: {processed:,} از {total_label}\n"
                      f"{bar}  {percent}%"
                  )

              async def _refresh_history_progress(force=False, status_override=None):
                  nonlocal last_progress_edit
                  now = time.monotonic()
                  if not force and now - last_progress_edit < 2.5:
                      return
                  await _edit_history_choice_panel(
                      _history_progress_text(status_override), buttons=[]
                  )
                  last_progress_edit = now

              # Replace the choice buttons immediately, so the panel visibly changes
              # before any channel/session preparation or history iteration begins.
              await _refresh_history_progress(force=True)
              totals = []
              for session_index, (sess, client) in enumerate(sessions, 1):
                  progress["session_index"] = session_index
                  progress["status"] = f"آماده‌سازی سشن {sess}"
                  await _refresh_history_progress(force=True)
                  try:
                      from telethon.tl.functions.messages import SendReactionRequest
                      from telethon.tl.types import ReactionEmoji
                      entity = await _resolve_autoseen_entity(client, channel)

                      # Telethon returns the total count for limit=0 on supported
                      # versions. If it is unavailable, use the latest message ID
                      # as an explicitly approximate denominator.
                      count_result = await client.get_messages(entity, limit=0)
                      total_value = getattr(count_result, "total", None)
                      if isinstance(total_value, int) and total_value >= 0:
                          session_history_total = total_value
                      else:
                          latest_for_count = await client.get_messages(entity, limit=1)
                          session_history_total = (
                              max(0, int(latest_for_count[0].id)) if latest_for_count else 0
                          )
                          progress["exact_total"] = False
                      if progress["total_per_session"] is None:
                          progress["total_per_session"] = session_history_total
                      elif session_history_total != progress["total_per_session"]:
                          progress["total_per_session"] = max(
                              int(progress["total_per_session"] or 0), session_history_total
                          )
                          progress["exact_total"] = False
                      progress["total"] = int(progress["total_per_session"] or 0) * len(sessions)
                      progress["status"] = f"در حال بررسی تاریخچه با سشن {sess}"
                      await _refresh_history_progress(force=True)

                      allowed_reactions = (await _get_channel_allowed_reactions(client, channel, refresh=True)
                                           if auto_allowed else [])
                      post_reactions = []
                      used_post_fallback = False
                      if auto_allowed and not allowed_reactions:
                          post_reactions = await _get_channel_post_reactions(
                              client, entity, channel, refresh=True
                          )
                          used_post_fallback = bool(post_reactions)
                      # A very old post may carry a reaction that is no longer
                      # present in the channel's current allowed list or recent pool.
                      # The history loop below inspects that post's own reactions too.
                      done = failed = 0
                      latest_id = 0
                      error_counts: Dict[str, int] = {}
                      error_samples: Dict[str, str] = {}
                      # Use the already-resolved entity so private numeric
                      # channels work with the access hash Telethon resolved.
                      async for msg in client.iter_messages(entity, reverse=True, limit=None):
                          if not msg:
                              continue
                          latest_id = max(latest_id, int(msg.id))
                          progress["processed"] += 1
                          if progress["processed"] % 10 == 0:
                              await _refresh_history_progress()
                          if getattr(msg, "out", False):
                              continue
                          try:
                              if auto_allowed:
                                  # Prefer reactions already present on this exact post;
                                  # otherwise use the channel-wide observed fallback pool.
                                  message_pool = _message_reaction_objects(msg) if not allowed_reactions else []
                                  reaction_pool = allowed_reactions or message_pool or post_reactions
                                  if not reaction_pool:
                                      failed += 1
                                      error_counts["no_observed_reaction"] = error_counts.get("no_observed_reaction", 0) + 1
                                      continue
                                  if not allowed_reactions:
                                      used_post_fallback = True
                                  chosen_reaction = random.choice(reaction_pool)
                              else:
                                  chosen_reaction = ReactionEmoji(emoticon=random.choice(emojis))
                              await client(SendReactionRequest(peer=entity, msg_id=msg.id, reaction=[chosen_reaction]))
                              done += 1
                              await asyncio.sleep(0.15)
                          except FloodWaitError as exc:
                              wait_seconds = max(1, int(getattr(exc, "seconds", 1)))
                              progress["status"] = f"محدودیت موقت تلگرام؛ مکث {wait_seconds} ثانیه‌ای"
                              await _refresh_history_progress(force=True)
                              await asyncio.sleep(wait_seconds)
                              try:
                                  if auto_allowed:
                                      message_pool = _message_reaction_objects(msg) if not allowed_reactions else []
                                      reaction_pool = allowed_reactions or message_pool or post_reactions
                                      if not reaction_pool:
                                          failed += 1
                                          error_counts["no_observed_reaction"] = error_counts.get("no_observed_reaction", 0) + 1
                                          continue
                                      if not allowed_reactions:
                                          used_post_fallback = True
                                      chosen_reaction = random.choice(reaction_pool)
                                  else:
                                      chosen_reaction = ReactionEmoji(emoticon=random.choice(emojis))
                                  await client(SendReactionRequest(peer=entity, msg_id=msg.id, reaction=[chosen_reaction]))
                                  done += 1
                                  await asyncio.sleep(0.15)
                              except Exception as retry_exc:
                                  failed += 1
                                  bucket = _autoreact_error_bucket(retry_exc)
                                  error_counts[bucket] = error_counts.get(bucket, 0) + 1
                                  error_samples.setdefault(bucket, f"{type(retry_exc).__name__}: {retry_exc}"[:180])
                          except Exception as exc:
                              failed += 1
                              bucket = _autoreact_error_bucket(exc)
                              error_counts[bucket] = error_counts.get(bucket, 0) + 1
                              error_samples.setdefault(bucket, f"{type(exc).__name__}: {exc}"[:180])
                      if latest_id:
                          _store_auto_cursor(gname, "autoreact", _session_cursor_key(str(channel), sess), latest_id)
                      reason_text = _autoreact_error_counts_text(error_counts)
                      totals.append(
                          f"{sess}: موفق {done}، ردشده {failed}"
                          + (" (استفاده از ری‌اکشن‌های باقی‌مانده روی پست‌ها)" if used_post_fallback else "")
                          + (f" ({reason_text})" if reason_text else "")
                      )
                      if failed:
                          sample = error_samples.get("other") or error_samples.get("flood_wait")
                          log.warning(
                              "[autoreact-history-summary:%s:%s] channel=%s success=%s rejected=%s reasons=%s%s",
                              gname, sess, channel, done, failed, reason_text or "unknown",
                              f" sample={sample}" if sample else "",
                          )
                  except Exception as exc:
                      totals.append(f"{sess}: خطا {str(exc)[:80]}")
                  progress["status"] = f"پردازش سشن {sess} تمام شد"
                  await _refresh_history_progress(force=True)
              progress["status"] = "پردازش تاریخچه تمام شد"
              await _refresh_history_progress(force=True)
              note = "\nنتیجهٔ پردازش تاریخچه (خطاهای تکراری به‌صورت خلاصه ثبت شدند):\n" + "\n".join(totals)
      else:
          sessions = _automation_sessions(gname, state)
          await event.answer("قانون ذخیره شد؛ فقط پست‌های جدید ری‌اکشن می‌گیرند.")
          callback_answered = True
          for sess, client in sessions:
              try:
                  entity = await _resolve_autoseen_entity(client, channel)
                  latest = await client.get_messages(entity, limit=1)
                  if latest:
                      _store_auto_cursor(gname, "autoreact", _session_cursor_key(str(channel), sess), int(latest[0].id))
              except Exception as exc:
                  log.warning("[autoreact:%s:%s] failed to set new-only baseline for %s: %s", gname, sess, channel, exc)
      if state.get("enabled"):
          _ensure_autoreact_loop(gname)
      if not callback_answered:
          await event.answer("قانون ذخیره شد")
      display_emojis = ("ری‌اکشن‌های مجاز کانال" if auto_allowed else " / ".join(emojis))
      await _edit_history_choice_panel(
          f"قانون ثبت شد: {channel} → {display_emojis}{note}",
          buttons=[[Button.inline("✨ ری‌اکشن خودکار", f"og_autoreact_{gname}".encode())]],
      )

    @bot.on(events.CallbackQuery(pattern=re.compile(rb"og_autoreact_del_(.+)\|(\d+)")))
    async def _og_autoreact_delete_cb(event):
      gname = event.pattern_match.group(1).decode()
      idx = int(event.pattern_match.group(2).decode())
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      state = _og_autoreact_state(gname)
      rules = state.get("rules", [])
      channel_rules = [(real_idx, rule) for real_idx, rule in enumerate(rules)
                       if isinstance(rule, dict) and rule.get("sender_id") is None]
      deleted = 0 <= idx < len(channel_rules)
      if deleted:
          real_idx, removed_rule = channel_rules[idx]
          rules.pop(real_idx)
          removed_channel = str(removed_rule.get("channel", ""))
          _autoreact_last_ids.setdefault(gname, {}).pop(removed_channel, None)
          _og_autoreact_state(gname).setdefault("last_ids", {}).pop(removed_channel, None)
          save_groups()
      await event.answer("قانون حذف شد" if deleted else "موردی پیدا نشد")
      await sp_edit(event, _og_autoreact_text(gname), buttons=_og_autoreact_buttons(gname))

    @bot.on(events.CallbackQuery(pattern=re.compile(rb"og_autoreact_clr_(.+)")))
    async def _og_autoreact_clear_cb(event):
      gname = event.pattern_match.group(1).decode()
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      state = _og_autoreact_state(gname)
      state["rules"] = [r for r in state.get("rules", [])
                        if isinstance(r, dict) and r.get("sender_id") is not None]
      state["enabled"] = False
      state["last_ids"] = {}
      _autoreact_last_ids.pop(gname, None)
      _stop_autoreact_loop(gname)
      save_groups()
      await event.answer("قوانین کانال پاک شدند؛ قوانین آیدی عددی جداگانه حفظ شدند")
      await sp_edit(event, _og_autoreact_text(gname), buttons=_og_autoreact_buttons(gname))

    @bot.on(events.CallbackQuery(pattern=re.compile(rb"og_autoreact_(?!tgl_|add_|multi_|clr_|del_|count_|allowed_|post_|all_|hist_)(.+)")))
    async def _og_autoreact_panel_cb(event):
      data = event.data.decode(errors="ignore")
      m = re.fullmatch(r"og_autoreact_(.+)", data)
      if not m or any(data.startswith(x) for x in ("og_autoreact_tgl_", "og_autoreact_add_", "og_autoreact_multi_", "og_autoreact_clr_", "og_autoreact_del_", "og_autoreact_count_", "og_autoreact_allowed_", "og_autoreact_post_", "og_autoreact_all_", "og_autoreact_hist_")):
          return
      gname = m.group(1)
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      await sp_edit(event, _og_autoreact_text(gname), buttons=_og_autoreact_buttons(gname))
      await event.answer()

    @bot.on(events.CallbackQuery(pattern=re.compile(rb"og_lang_(.+)")))
    async def og_lang_cb(event):
      gname = event.pattern_match.group(1).decode()
      if not og_guard(event, gname):
          return await event.answer(" دسترسی ندارید", alert=True)
      uid = event.sender_id
      cur = _remote_panel_language(gname)
      groups_db.setdefault(gname, {})["panel_language"] = "en" if cur == "fa" else "fa"
      og_panel_lang[(gname, uid)] = groups_db[gname]["panel_language"]
      save_groups()
      cnt = len(og_sessions(gname))
      online = sum(1 for s in og_sessions(gname) if s in managed)
      if groups_db[gname]["panel_language"] == "en":
          txt = (f" Remote management: {gname}\n━━━━━━━━━━━━━━━━━━━━\n"
                   f" Accounts: {cnt}   Online: {online}\n"
                   f"Pick an option:")
      else:
          txt = (f" مدیریت ریموت: {gname}\n━━━━━━━━━━━━━━━━━━━━\n"
                   f" اکانت: {cnt}   آنلاین: {online}\n"
                   f"یه گزینه انتخاب کن:")
      await sp_edit(event, txt, buttons=og_menu(gname, uid))
      await event.answer()

    @bot.on(events.CallbackQuery(pattern=re.compile(rb"og_home_(.+)")))
    async def og_home_cb(event):
      gname = event.pattern_match.group(1).decode()
      if not _og_has_permission(event, gname):
          return await event.answer(" دسترسی ندارید", alert=True)
      if event.sender_id != OWNER_ID and is_group_expired(gname):
          await sp_edit(event,
              f"⚠️ ریموت «{gname}»\n━━━━━━━━━━━━━━\n"
              f"اشتراک این ریموت منقضی شده.\n"
              f"لطفاً اشتراک خود را آپدیت کنید.",
              buttons=[[Button.inline("🔄 Refresh", f"og_home_{gname}".encode())]])
          return await event.answer()
      cnt = len(og_sessions(gname))
      online = sum(1 for s in og_sessions(gname) if s in managed)
      txt = (
          f" مدیریت ریموت: {gname}\n"
          f"━━━━━━━━━━━━━━━━━━━━\n"
          f" اکانت: {cnt}   آنلاین: {online}\n"
          f"یه گزینه انتخاب کن:"
      )
      await sp_edit(event, txt, buttons=og_menu(gname, event.sender_id))
      await event.answer(" رفرش شد")

