    async def _render_bulk_group_picker(event, gname, page=0):
      sessions = og_sessions(gname)
      if not sessions:
          return await sp_edit(event, "این ریموت سشنی ندارد.",
                               buttons=[[Button.inline("🔙 بازگشت", f"og_act_{gname}".encode())]])
      joined = await _fetch_joined_groups(sessions)
      if not joined:
          return await sp_edit(event, "هیچ گروهی که سشن‌های همین ریموت عضو آن باشند پیدا نشد.",
                               buttons=[[Button.inline("🔙 بازگشت", f"og_act_{gname}".encode())]])
      cfg = _bulk_cfg(gname)
      target_set = set(cfg.get("targets", []))
      labels = cfg.setdefault("target_labels", {})
      page_size = 30
      total_pages = max(1, (len(joined) + page_size - 1) // page_size)
      page = max(0, min(int(page or 0), total_pages - 1))
      rows = []
      for title, gid in joined[page * page_size:(page + 1) * page_size]:
          cid = str(gid)
          labels[cid] = str(title)[:60]
          mark = "✅" if cid in target_set else "☐"
          button_text = f"{mark} {str(title)[:35]}"
