    async def og_actstart_cb(event):
      gname = event.pattern_match.group(1).decode()
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      cfg = _bulk_cfg(gname)
      targets = list(dict.fromkeys(str(x) for x in cfg.get("targets", [])))
      if not targets:
          return await event.answer("اول حداقل یک گروه انتخاب کن", alert=True)
      if not og_sessions(gname):
          return await event.answer("این ریموت هیچ سشنی ندارد", alert=True)
      if cfg.get("action") not in _ACTION_MAP:
          return await event.answer("اول اکشن را انتخاب کن", alert=True)
      cfg["enabled"] = True
      save_groups()
      for chat_id in targets:
          _BULK_ACTION_LAST_TRIGGER[(gname, str(chat_id))] = time.monotonic()
          _trigger_remote_bulk_action(gname, chat_id, cfg["action"])
      await event.answer(f"شروع شد؛ اجرای ۳ ثانیه‌ای، با فاصله تریگر {cfg.get('interval', 3)} ثانیه")
      await sp_edit(event, _act_panel_text(gname), buttons=_act_buttons(gname))

