      gname = event.pattern_match.group(1).decode()
      if not og_guard(event, gname):
          return await event.answer("دسترسی ندارید", alert=True)
      cfg = _bulk_cfg(gname)
      cfg["enabled"] = False
      save_groups()
      for key, task in list(_BULK_ACTION_BURSTS.items()):
          if key[0] == gname and task and not task.done():
              task.cancel()
      for key in list(_BULK_ACTION_LAST_TRIGGER):
          if key[0] == gname:
              _BULK_ACTION_LAST_TRIGGER.pop(key, None)
      await event.answer("Bulk Action متوقف شد")
      await sp_edit(event, _act_panel_text(gname), buttons=_act_buttons(gname))

