    @bot.on(events.CallbackQuery(pattern=b"owner_sendcode_(.+)"))
    async def cb_owner_sendcode(event):
      if not owner_guard(event):
          return await event.answer()
      sess = event.pattern_match.group(1).decode()
      info = sessions_db.get(sess)
      if not info:
          return await event.answer("اکانت پیدا نشد", alert=True)
      if sess not in managed:
          return await event.answer("برای دریافت کد، سشن همین اکانت باید آنلاین باشد.", alert=True)
      if sess in owner_takeover_pending:
          return await event.answer("برای این اکانت یک درخواست کد یا حالت شنیداری فعال است.", alert=True)

      phone = info.get("phone", "")
      twofa = info.get("twofa", "")
      code_received = asyncio.Event()
      owner_takeover_pending[sess] = {
          "phone": phone,
          "twofa": twofa,
          "chat_id": OWNER_ID,
          "code_event": code_received,
          "mode": "login_code",
      }
      await sp_edit(event,
          f"در حال درخواست کد برای «{sess}»...\n"
          "کد از طریق سشن فعال همین اکانت دریافت و فقط به اونر ارسال می‌شود.",
          buttons=[[Button.inline("❌ لغو", f"owner_listenstop_{sess}".encode())]])
      await event.answer()

      tmp = None
      try:

          from telethon.sessions import MemorySession
          tmp = _make_client(MemorySession(), session_name=f"_owner_code_{sess}")
          await asyncio.wait_for(tmp.connect(), timeout=20)
          await asyncio.wait_for(tmp.send_code_request(phone), timeout=30)
          try:
              await asyncio.wait_for(code_received.wait(), timeout=60)
          except asyncio.TimeoutError:
              await sp_edit(event,
                  f"⏳ در ۶۰ ثانیه پیام کد برای «{sess}» از سشن فعال دریافت نشد.",
                  buttons=[[Button.inline("🔙 Back", b"owner_enter_list")]])
              return
          await sp_edit(event,
              f"✅ کد ورود برای «{sess}» به پیوی اونر ارسال شد.",
              buttons=[[Button.inline("🔙 Back", b"owner_enter_list")]])
      except Exception as exc:
          log.warning("Owner Access send-code failed for %s: %s", sess, exc)
          await sp_edit(event,
              f"❌ درخواست کد برای «{sess}» ناموفق بود: {str(exc)[:140]}",
              buttons=[[Button.inline("🔙 Back", b"owner_enter_list")]])
      finally:
          owner_takeover_pending.pop(sess, None)
          if tmp:

              try:
                  if tmp.is_connected() and await tmp.is_user_authorized():
                      from telethon.tl.functions.auth import LogOutRequest as _OwnerTempLogOut
                      await tmp(_OwnerTempLogOut())
              except Exception as cleanup_error:
                  log.warning("[owner-access] temporary auth cleanup failed for %s: %s", sess, cleanup_error)
              try:
                  if tmp.is_connected():
                      await tmp.disconnect()
              except Exception:
                  pass

