                        save_session_state(og_sess, meta["state"])
                        await sp(event.chat_id, f" دشمن {eid} به {og_sess} اضافه شد.",
                                buttons=[[Button.inline("🔙 Back", f"og_en1_{og_gname}|{og_sess}".encode())]])
