    tabchi_active = {"running": False}
    _tabchi_task = {"task": None}

    def _tabchi_cfg():
      cfg = groups_db.setdefault(group_name, {}).setdefault("tabchi", {
          "session": "", "source_link": "", "interval": 1800
      })

      cfg.pop("destinations", None)
      cfg.pop("_run_destinations", None)
      return cfg

    def _tabchi_connected_client(sess):
      if sess not in grp_sessions():
          return None
      meta = managed.get(sess)
      client = meta.get("client") if isinstance(meta, dict) else None
      if client is None:
          return None
      try:
          if hasattr(client, "is_connected") and not client.is_connected():
              return None
      except Exception:
          return None
      return client

    async def _tabchi_discover_authorized_groups(client):
      """Return joined groups where Telegram does not restrict sending messages."""
      from telethon import utils as _tg_utils
      discovered = []
      seen = set()
      async for dialog in client.iter_dialogs():
          entity = getattr(dialog, "entity", None)
          if entity is None or getattr(entity, "left", False) or getattr(entity, "deactivated", False):
              continue
          is_group_entity = isinstance(entity, types.Chat) or bool(getattr(entity, "megagroup", False))
          if not is_group_entity:
              continue
          banned = getattr(entity, "banned_rights", None) or getattr(entity, "default_banned_rights", None)
          if banned is not None and bool(getattr(banned, "send_messages", False)):
              continue
          try:
              peer_id = str(_tg_utils.get_peer_id(entity))
          except Exception:
              continue
          if peer_id not in seen:
              seen.add(peer_id)
              discovered.append(peer_id)
      return discovered

