    async def _tabchi_get_source_message(client, link):
      """Resolve a public/private t.me message link to its Telegram message."""
      from telethon.tl.types import PeerChannel
      raw = (link or "").strip()
      m_private = re.search(r"(?:https?://)?(?:www\.)?(?:t\.me|telegram\.me)/c/(\d+)/(\d+)", raw)
      if m_private:
          channel_id, message_id = int(m_private.group(1)), int(m_private.group(2))
          peer = PeerChannel(channel_id)
          entity = await client.get_entity(peer)
      else:
          m_public = re.search(r"(?:https?://)?(?:www\.)?(?:t\.me|telegram\.me)/(?:s/)?([A-Za-z0-9_]+)/([0-9]+)", raw)
          if not m_public:
              raise ValueError("فرمت لینک معتبر نیست؛ لینک یک پست از t.me لازم است.")
          username, message_id = m_public.group(1), int(m_public.group(2))
          entity = await client.get_entity("@" + username)
      msg = await client.get_messages(entity, ids=message_id)
      if not msg:
          raise ValueError("پیام پیدا نشد یا اکانت به پیام مبدأ دسترسی ندارد.")
      return msg

    async def _tabchi_forward_batch(chat_id):
      cfg = _tabchi_cfg()
      sess = cfg.get("session", "")
      client = _tabchi_connected_client(sess)
      if not client:
          raise RuntimeError("اکانت انتخابی متصل نیست؛ ابتدا آن را روشن کن.")
      link = cfg.get("source_link", "")
      if not link:
          raise RuntimeError("لینک پیام ثبت نشده است.")

      source_msg = await _tabchi_get_source_message(client, link)
      authorized_groups = await _tabchi_discover_authorized_groups(client)
      if not authorized_groups:
          await sp(
              chat_id,
              "برای این اکانت گروه جوین‌شده‌ای با اجازه ارسال پیام پیدا نشد.",
              buttons=[[Button.inline("📨 بازگشت به تبچی", b"g_tabchi")]],
          )
          return

      destinations = random.sample(authorized_groups, min(5, len(authorized_groups)))
      ok = fail = skipped = 0
      details = []
      for index, dest in enumerate(destinations):
          if not tabchi_active["running"]:
              break
          try:
              entity = await client.get_entity(int(dest) if re.fullmatch(r"-?\d+", dest) else dest)
              is_group_entity = isinstance(entity, types.Chat) or bool(getattr(entity, "megagroup", False))
              if not is_group_entity:
                  skipped += 1
                  details.append(f"⏭ {dest}: مقصد دیگر گروه نیست")
                  continue
              banned = getattr(entity, "banned_rights", None) or getattr(entity, "default_banned_rights", None)
              if banned is not None and bool(getattr(banned, "send_messages", False)):
                  skipped += 1
                  details.append(f"⏭ {getattr(entity, 'title', dest)}: اجازه ارسال پیام ندارد")
                  continue
              await client.forward_messages(entity, source_msg)
              ok += 1
              details.append(f"✅ {getattr(entity, 'title', dest)}")
          except Exception as exc:
              fail += 1
              details.append(f"❌ {dest}: {str(exc)[:90]}")
          if index < len(destinations) - 1 and tabchi_active["running"]:
              await asyncio.sleep(2)

      interval = max(1800, int(cfg.get("interval", 1800) or 1800))
      summary = (
          f"گزارش نوبت تبچی — ریموت {group_name}\n"
          f"اکانت: {sess}\n"
          f"انتخاب‌شده: {len(destinations)} | موفق: {ok} | ناموفق: {fail} | ردشده: {skipped}\n"
          f"نوبت بعدی پس از {interval // 60} دقیقه\n\n"
          + "\n".join(details[:5])
      )
      await sp(chat_id, summary, buttons=[[Button.inline("📨 بازگشت به تبچی", b"g_tabchi")]])

    async def _tabchi_periodic_loop(chat_id):
      while tabchi_active["running"]:
          try:
              await _tabchi_forward_batch(chat_id)
          except asyncio.CancelledError:
              raise
          except Exception as exc:
              log.warning("[tabchi:%s] scheduled batch failed: %s", group_name, exc)
              try:
                  await sp(
                      chat_id,
                      f"خطای این نوبت تبچی: {str(exc)[:160]}\nتبچی روشن می‌ماند و در نوبت بعدی دوباره تلاش می‌کند.",
                      buttons=[[Button.inline("📨 بازگشت به تبچی", b"g_tabchi")]],
                  )
              except Exception:
                  pass

          if not tabchi_active["running"]:
              break
          cfg = _tabchi_cfg()
          interval = max(1800, int(cfg.get("interval", 1800) or 1800))
          await asyncio.sleep(interval)

    async def _tabchi_run_guarded(chat_id):
      try:
          await _tabchi_periodic_loop(chat_id)
      except asyncio.CancelledError:
          pass
      except Exception as exc:
          logging.exception("Tabchi scheduled forwarding failed for remote %s", group_name)
          try:
              await sp(chat_id, f"خطای اجرای تبچی: {str(exc)[:180]}")
          except Exception:
              pass
      finally:
          tabchi_active["running"] = False
          _tabchi_task["task"] = None
          try:
              await sp(chat_id, _tabchi_panel_text(), buttons=_tabchi_buttons())
          except Exception:
              pass

    @bot.on(events.CallbackQuery(data=b"gtab_send"))
    async def gtab_send_cb(event):
      if not grp_guard(event):
          return await event.answer()
      cfg = _tabchi_cfg()
      if tabchi_active["running"]:
          tabchi_active["running"] = False
          task = _tabchi_task.get("task")
          if task and not task.done():
              task.cancel()
          await event.answer("تبچی خاموش شد؛ ارسال دوره‌ای متوقف می‌شود.")
          await sp_edit(event, _tabchi_panel_text(), buttons=_tabchi_buttons())
          return

      sess = cfg.get("session", "")
      client = _tabchi_connected_client(sess)
      if not client:
          return await event.answer("ابتدا یک اکانت آنلاین انتخاب کن.", alert=True)
      if not cfg.get("source_link"):
          return await event.answer("ابتدا لینک پیام را ثبت کن.", alert=True)
      try:
          authorized_groups = await _tabchi_discover_authorized_groups(client)
          if not authorized_groups:
              return await event.answer(
                  "هیچ گروه جوین‌شده‌ای با اجازه ارسال پیام پیدا نشد.",
                  alert=True,
              )
      except Exception as exc:
          log.warning("[tabchi:%s] authorized group discovery failed: %s", group_name, exc)
          return await event.answer("خطا در شناسایی گروه‌های جوین‌شده؛ گزارش برنامه را بررسی کن.", alert=True)

      interval = max(1800, int(cfg.get("interval", 1800) or 1800))
      cfg["interval"] = interval
      save_groups()
      tabchi_active["running"] = True
      _tabchi_task["task"] = asyncio.create_task(_tabchi_run_guarded(event.chat_id))
      await event.answer(f"تبچی روشن شد؛ {len(authorized_groups)} گروه جوین‌شده با اجازه ارسال پیدا شد.")
      await sp_edit(event, _tabchi_panel_text(), buttons=_tabchi_buttons())

