    # ---------------- Referral Bot: one extractor, all-session choice ----------------
    def _referral_cfg():
      cfg = groups_db.setdefault(group_name, {}).setdefault("referral_bot", {})
      if not isinstance(cfg, dict):
          cfg = {}
          groups_db[group_name]["referral_bot"] = cfg
      cfg.setdefault("link", "")
      cfg.setdefault("done_sessions", [])
      cfg.setdefault("last_results", {})
      cfg.setdefault("last_result", "")
      cfg.setdefault("started_at", "")
      cfg.setdefault("button_options", [])
      cfg.setdefault("extract_session", "")
      return cfg

    def _referral_panel_text():
      cfg = _referral_cfg()
      sessions = list(dict.fromkeys(grp_sessions()))
      done = set(cfg.get("done_sessions") or [])
      online = [s for s in sessions if managed.get(s) and managed[s].get("client")]
      options = cfg.get("button_options") or []
      option_lines = "\n".join(f"  {i+1}. {x.get('text','')}" for i, x in enumerate(options)) or "  هنوز دکمه‌ای استخراج نشده"
      completed = len(done.intersection(sessions))
      return (
          f"🎟 Referral Bot — ریموت {group_name}\n"
          f"━━━━━━━━━━━━━━━━━━\n"
          f"لینک استارت: {cfg.get('link') or '— ثبت نشده —'}\n"
          f"کل سشن‌ها: {len(sessions)} | آنلاین: {len(online)} | قبلاً موفق: {completed}\n"
          f"سشن استخراج‌کننده: {cfg.get('extract_session') or '—'}\n"
          f"دکمه‌های استخراج‌شده:\n{option_lines}\n"
          f"نتیجه آخر: {cfg.get('last_result') or '—'}\n"
          f"━━━━━━━━━━━━━━━━━━\n"
          f"فقط یک سشن دکمه‌ها را استخراج می‌کند؛ انتخاب هر دکمه روی همه سشن‌های همین ریموت اعمال می‌شود."
      )

    def _referral_panel_buttons():
      cfg = _referral_cfg()
      rows = [
          [Button.inline("🔗 ثبت لینک استارت", b"gref_link")],
          [Button.inline("▶️ استارت همه سشن‌های ریموت", b"gref_run")],
      ]
      for i, item in enumerate(cfg.get("button_options") or []):
          label = str(item.get("text") or f"گزینه {i+1}")[:50]
          rows.append([Button.inline(f"🖱 انتخاب: {label}", f"gref_choose_{i}".encode())])
      rows.append([Button.inline("🔙 بازگشت", b"g_home")])
      return rows

