    async def _referral_find_buttons(client, bot_entity, limit=30):
      try:
          messages = await client.get_messages(bot_entity, limit=limit)
      except Exception:
          return []
      found = []
      seen = set()
      for msg in messages:
          markup = getattr(msg, "reply_markup", None)
          for row in getattr(markup, "rows", []) or []:
              for btn in getattr(row, "buttons", []) or []:
                  data = getattr(btn, "data", None)
                  label = str(getattr(btn, "text", "") or "").strip()
                  if data and label:
                      key = (label, bytes(data).hex())
                      if key not in seen:
                          seen.add(key)
                          found.append({"text": label[:64], "data_hex": key[1]})
      return found

    @bot.on(events.CallbackQuery(data=b"gref_run"))
    async def gref_run_all_sessions(event):
      if not grp_guard(event):
          return await event.answer()
      cfg = _referral_cfg()
      link = str(cfg.get("link") or "").strip()
      if not link:
          return await event.answer("اول لینک استارت را ثبت کن.", alert=True)
      if referral_run_lock.locked():
          return await event.answer("یک عملیات Referral در همین ریموت در حال اجراست.", alert=True)
      target = _parse_referral_bot_target(link)
      if not target:
          return await event.answer("یوزرنیم یا لینک معتبر نیست؛ نمونه: @amir_bot یا https://t.me/amir_bot?start=ABC123", alert=True)
      username, payload = target
      sessions = list(dict.fromkeys(grp_sessions()))
      if not sessions:
          return await event.answer("این ریموت هیچ سشنی ندارد.", alert=True)

      async with referral_run_lock:
          await event.answer(f"در حال استارت {len(sessions)} سشن؛ استخراج دکمه‌ها فقط با یک سشن انجام می‌شود...")
          done = set(cfg.get("done_sessions") or [])
          async def _start_one(sess):
              meta = managed.get(sess)
              client = meta.get("client") if meta else None
              if not client:
                  return sess, "آفلاین"
              if sess in done:
                  return sess, "قبلاً موفق"
              try:
                  bot_entity = await client.get_entity(username)
                  if not getattr(bot_entity, "bot", False):
                      raise ValueError("یوزرنیم لینک متعلق به ربات نیست.")
                  bot_input = types.InputUser(int(bot_entity.id), int(bot_entity.access_hash))
                  if payload:
                      await client(functions.messages.StartBotRequest(
                          bot=bot_input, peer=types.InputPeerSelf(),
                          random_id=random.getrandbits(63), start_param=payload))
                  else:
                      await client.send_message(bot_entity, "/start")
                  return sess, "موفق"
              except Exception as exc:
                  return sess, f"خطا: {type(exc).__name__}: {str(exc)[:100]}"

          results = await asyncio.gather(*(_start_one(s) for s in sessions))
          result_map = {s: status for s, status in results}
          for s, status in results:
              if status == "موفق":
                  done.add(s)
          cfg["done_sessions"] = sorted(done)
          cfg["last_results"] = result_map

          # Extract inline callback buttons from exactly one successful/online session.
          extractor = next((s for s, status in results if status in ("موفق", "قبلاً موفق")
                            and managed.get(s) and managed[s].get("client")), None)
          options = []
          if extractor:
              client = managed[extractor]["client"]
              try:
                  bot_entity = await client.get_entity(username)
                  for _ in range(20):
                      options = await _referral_find_buttons(client, bot_entity)
                      if options:
                          break
                      await asyncio.sleep(1)
              except Exception:
                  options = []
          cfg["extract_session"] = extractor or ""
          cfg["button_options"] = options
          success = sum(st == "موفق" for _, st in results)
          offline = sum(st == "آفلاین" for _, st in results)
          already = sum(st == "قبلاً موفق" for _, st in results)
          failed = sum(st.startswith("خطا:") for _, st in results)
          cfg["last_result"] = (f"استارت موفق: {success} | آفلاین: {offline} | قبلی: {already} "
                                f"| خطا: {failed} | دکمه استخراج‌شده: {len(options)}")
          cfg["started_at"] = datetime.utcnow().isoformat(timespec="seconds")
          save_groups()
          details = "\n".join(f"• {s}: {st}" for s, st in results[:50])
          if len(results) > 50:
              details += f"\n... و {len(results)-50} سشن دیگر"
          if extractor and not options:
              details += "\n⚠️ از پیام‌های سشن استخراج‌کننده دکمه Callback پیدا نشد."
          await sp_edit(event, _referral_panel_text() + "\n\nگزارش:\n" + details,
                        buttons=_referral_panel_buttons())

    @bot.on(events.CallbackQuery(pattern=b"gref_choose_(\\d+)"))
    async def gref_choose_button_all(event):
      if not grp_guard(event):
          return await event.answer()
      cfg = _referral_cfg()
      idx = int(event.pattern_match.group(1))
      options = cfg.get("button_options") or []
      if idx < 0 or idx >= len(options):
          return await event.answer("این گزینه دیگر معتبر نیست؛ دوباره دکمه‌ها را استخراج کن.", alert=True)
      if referral_run_lock.locked():
          return await event.answer("عملیات دیگری در همین ریموت در حال اجراست.", alert=True)
      option = options[idx]
      try:
          callback_data = bytes.fromhex(option.get("data_hex", ""))
      except Exception:
          return await event.answer("اطلاعات دکمه معتبر نیست.", alert=True)
      link = str(cfg.get("link") or "")
      target = _parse_referral_bot_target(link)
      if not target:
          return await event.answer("یوزرنیم یا لینک ربات معتبر نیست.", alert=True)
      username = target[0]
      sessions = list(dict.fromkeys(grp_sessions()))
      async with referral_run_lock:
          await event.answer(f"در حال انتخاب «{option.get('text','')}» روی همه سشن‌ها...")
          async def _click_one(sess):
              meta = managed.get(sess)
              client = meta.get("client") if meta else None
              if not client:
                  return sess, "آفلاین"
              try:
                  bot_entity = await client.get_entity(username)
                  messages = await client.get_messages(bot_entity, limit=30)
                  for msg in messages:
                      markup = getattr(msg, "reply_markup", None)
                      for row in getattr(markup, "rows", []) or []:
                          for btn in getattr(row, "buttons", []) or []:
                              if getattr(btn, "data", None) and bytes(btn.data) == callback_data:
                                  await client(functions.messages.GetBotCallbackAnswerRequest(
                                      peer=bot_entity, msg_id=msg.id, data=callback_data))
                                  return sess, "انتخاب شد"
                  return sess, "پیام دارای این دکمه پیدا نشد"
              except Exception as exc:
                  return sess, f"خطا: {type(exc).__name__}: {str(exc)[:90]}"
          click_results = await asyncio.gather(*(_click_one(s) for s in sessions))
          ok = sum(st == "انتخاب شد" for _, st in click_results)
          cfg["last_result"] = f"انتخاب «{option.get('text','')}»: موفق {ok}/{len(sessions)}"
          cfg["last_results"] = {s: st for s, st in click_results}

          # After the selected button is pressed, inspect the next screen using
          # the same single extractor session. If another inline keyboard appears,
          # publish its labels so the operator can continue the flow.
          extractor = str(cfg.get("extract_session") or "")
          next_options = []
          extractor_meta = managed.get(extractor) if extractor else None
          extractor_client = extractor_meta.get("client") if extractor_meta else None
          if extractor_client:
              try:
                  bot_entity = await extractor_client.get_entity(username)
                  for _ in range(20):
                      next_options = await _referral_find_buttons(extractor_client, bot_entity)
                      if next_options:
                          break
                      await asyncio.sleep(1)
              except Exception:
                  next_options = []
          cfg["button_options"] = next_options
          save_groups()
          details = "\n".join(f"• {s}: {st}" for s, st in click_results[:50])
          if len(click_results) > 50:
              details += f"\n... و {len(click_results)-50} سشن دیگر"
          if next_options:
              details += "\n\nدکمه‌های مرحله بعد از سشن استخراج‌کننده دریافت شدند. برای ادامه، گزینه بعدی را انتخاب کن."
          else:
              details += "\n\nدر صفحه بعدی دکمه شیشه‌ای دیگری پیدا نشد. اگر ربات بعداً دکمه‌ای نشان داد، دوباره از همین پنل بررسی کن."
          await sp_edit(event, _referral_panel_text() + "\n\nگزارش انتخاب:\n" + details,
                        buttons=_referral_panel_buttons())
    # -------------------------------------------------------------------------

